/* Việt Sử V5.9 — nhân vật, sự kiện, dòng thời gian Hồ Chí Minh (sinh bởi tools/build_v59.py, đừng sửa tay) */
window.VS59_DATA={"phien_ban":"5.9.1","nhan_vat":[{"id":"vs59-lytutrong","name":"Lý Tự Trọng","period":"1914–1931","role":"Thanh niên cộng sản, liên lạc của Xứ ủy Nam Kì","nhom":"Anh hùng liệt sĩ tuổi trẻ","nam":1931,"bio":["Tên thật là Lê Văn Trọng, quê gốc Thạch Hà (Hà Tĩnh), sinh ra trong một gia đình Việt kiều yêu nước ở Thái Lan. Năm 1923, mới 10 tuổi, anh được đưa sang Trung Quốc học, giỏi tiếng Hán và tiếng Anh, sinh hoạt trong Hội Việt Nam Cách mạng Thanh niên.","Năm 1929, anh về nước làm liên lạc cho Xứ ủy Nam Kì và các đồng chí ở nước ngoài qua những chuyến tàu cập cảng Sài Gòn. Ngày 9/2/1931, trong một buổi mít tinh kỉ niệm khởi nghĩa Yên Bái, anh bắn chết viên thanh tra mật thám Lơ-gơ-răng để bảo vệ người diễn thuyết, rồi bị bắt và tra tấn.","Trước tòa, anh khẳng định mình hành động có suy nghĩ, vì mục đích cách mạng. Ngày 21/11/1931, anh bị đưa lên máy chém khi mới 17 tuổi, trước lúc hi sinh vẫn hô vang tên Tổ quốc. Tên anh được đặt cho Huy hiệu và nhiều trường học, đường phố."],"src":"Những tấm gương anh hùng liệt sĩ của tuổi trẻ Việt Nam (Ban Tuyên giáo Tỉnh đoàn Bến Tre, 2014)"},{"id":"vs59-vothisau","name":"Võ Thị Sáu","period":"1933–1952","role":"Nữ chiến sĩ Công an xung phong Đất Đỏ","nhom":"Anh hùng liệt sĩ tuổi trẻ","nam":1952,"bio":["Sinh năm 1933 trong một gia đình nghèo ở Phước Thọ, Đất Đỏ (Bà Rịa). Năm 14 tuổi, chị gia nhập Đội Công an xung phong quận Đất Đỏ, làm liên lạc, nắm tình hình địch ở vùng tạm chiếm.","Chị từng phá cuộc mít tinh kỉ niệm Quốc khánh Pháp năm 1948 và dùng lựu đạn đánh bọn tề, ác ôn. Tháng 2/1950, chị bị bắt, bị tra tấn ở khám Chí Hòa nhưng không khai báo, rồi bị kết án tử hình dù chưa đến tuổi thành niên.","Chị bị đày ra Côn Đảo, được kết nạp Đảng trong tù và bị xử bắn sáng 23/1/1952, trước họng súng vẫn hô khẩu hiệu cách mạng. Năm 1993, chị được truy tặng danh hiệu Anh hùng Lực lượng vũ trang nhân dân."],"src":"Những tấm gương anh hùng liệt sĩ của tuổi trẻ Việt Nam (Ban Tuyên giáo Tỉnh đoàn Bến Tre, 2014)"},{"id":"vs59-tranvanon","name":"Trần Văn Ơn","period":"1931–1950","role":"Học sinh yêu nước trường Pétrus Ký","nhom":"Anh hùng liệt sĩ tuổi trẻ","nam":1950,"bio":["Sinh ngày 29/5/1931 ở Phước Thạnh, Châu Thành (Bến Tre), anh học ở trường Pétrus Ký (Sài Gòn) và là một cột trụ của phong trào học sinh yêu nước trong trường, hội viên bí mật của Đoàn học sinh kháng chiến nội thành.","Ngày 9/1/1950, hơn 6.000 học sinh, sinh viên, giáo viên Sài Gòn biểu tình đòi thả học sinh bị bắt. Khi bị đàn áp, anh xông ra che chở cho các bạn nhỏ tuổi và nữ sinh rút lui, rồi bị bắn hi sinh khi chưa đầy 19 tuổi.","Đám tang anh ngày 12/1/1950 trở thành cuộc biểu dương lực lượng của nhân dân Sài Gòn – Gia Định. Ngày 9/1 được chọn làm Ngày truyền thống học sinh, sinh viên Việt Nam; năm 2000 anh được truy tặng Anh hùng Lực lượng vũ trang nhân dân."],"src":"Những tấm gương anh hùng liệt sĩ của tuổi trẻ Việt Nam (Ban Tuyên giáo Tỉnh đoàn Bến Tre, 2014)"},{"id":"vs59-nguyenvantroi","name":"Nguyễn Văn Trỗi","period":"1940–1964","role":"Chiến sĩ Biệt động Sài Gòn","nhom":"Anh hùng liệt sĩ tuổi trẻ","nam":1964,"bio":["Sinh ngày 1/2/1940 ở Điện Bàn (Quảng Nam), sau năm 1954 theo gia đình vào Sài Gòn, làm thợ điện ở nhà máy điện Chợ Quán và tham gia lực lượng Biệt động thành.","Tháng 5/1964, anh xin đi thay một đồng đội đã có con nhỏ, nhận nhiệm vụ đặt mìn ở cầu Công Lý để đánh phái đoàn của Bộ trưởng Quốc phòng Mĩ McNamara. Việc bị lộ, anh bị bắt đêm 9/5/1964.","Ngày 15/10/1964, anh bị xử bắn ở khám Chí Hòa; anh từ chối bịt mắt và hô vang khẩu hiệu đến phút cuối. Hình ảnh người thanh niên hiên ngang trước pháp trường trở thành biểu tượng của tuổi trẻ thời chống Mĩ."],"src":"Những tấm gương anh hùng liệt sĩ của tuổi trẻ Việt Nam (Ban Tuyên giáo Tỉnh đoàn Bến Tre, 2014)"},{"id":"vs59-nguyenvancu","name":"Nguyễn Văn Cừ","period":"1912–1941","role":"Tổng Bí thư Đảng Cộng sản Đông Dương (1938–1940)","nhom":"Anh hùng liệt sĩ tuổi trẻ","nam":1938,"bio":["Sinh ngày 9/7/1912 trong một gia đình nhà nho ở Phù Khê, Từ Sơn (Bắc Ninh). Năm 1927 tham gia Hội Việt Nam Cách mạng Thanh niên, năm 1929 vào chi bộ cộng sản đầu tiên ở Hà Nội; bị Pháp bắt và đày ra Côn Đảo.","Ra tù năm 1936, ông khôi phục cơ sở đảng ở Bắc Kì; năm 1938, mới 26 tuổi, ông được bầu làm Tổng Bí thư. Ông chỉ đạo Hội nghị Trung ương tháng 11/1939 chuyển hướng chiến lược, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu; tác phẩm Tự chỉ trích là bài học về tự phê bình.","Tháng 6/1940, ông bị bắt ở Sài Gòn, bị khép tội chịu trách nhiệm tinh thần về khởi nghĩa Nam Kì và bị xử bắn ngày 28/8/1941 ở Hóc Môn cùng Hà Huy Tập, Nguyễn Thị Minh Khai, Võ Văn Tần và nhiều đồng chí khác."],"src":"Những tấm gương anh hùng liệt sĩ của tuổi trẻ Việt Nam (Ban Tuyên giáo Tỉnh đoàn Bến Tre, 2014)"},{"id":"vs59-cuchinhlan","name":"Cù Chính Lan","period":"1930–1951","role":"Tiểu đội trưởng, Đại đoàn 304","nhom":"Anh hùng liệt sĩ tuổi trẻ","nam":1951,"bio":["Sinh năm 1930 trong một gia đình nông dân nghèo ở Quỳnh Đôi, Quỳnh Lưu (Nghệ An), mồ côi mẹ sớm. Năm 1946, mới 16 tuổi, anh xin gia nhập Vệ quốc đoàn.","Trong chiến dịch Hòa Bình, ngày 13/12/1951 khi đánh cứ điểm Giang Mở, anh đuổi theo, nhảy lên xe tăng địch, mở nắp tháp thả lựu đạn vào trong, làm chiếc xe đi đầu chết máy chắn đường cả đoàn xe.","Ngày 29/12/1951, đánh đồn Cô Tô, anh bị thương ba lần vẫn mở đường cho đồng đội và hi sinh khi trận đánh kết thúc. Năm 1952, anh là một trong bảy người đầu tiên được truy tặng danh hiệu Anh hùng Lực lượng vũ trang nhân dân."],"src":"Những tấm gương anh hùng liệt sĩ của tuổi trẻ Việt Nam (Ban Tuyên giáo Tỉnh đoàn Bến Tre, 2014)"},{"id":"vs59-vuadinh","name":"Vừ A Dính","period":"1934–1949","role":"Liên lạc đội vũ trang huyện Tuần Giáo","nhom":"Anh hùng liệt sĩ tuổi trẻ","nam":1949,"bio":["Người dân tộc Mông, sinh ngày 12/9/1934 ở bản Đề Chia, xã Pú Nhung, huyện Tuần Giáo (nay thuộc Điện Biên), trong một gia đình là cơ sở cách mạng; cha mẹ anh đều là liệt sĩ.","Năm 13 tuổi, anh trở thành liên lạc của đội vũ trang huyện Tuần Giáo, hoạt động khắp vùng Điện Biên, Tuần Giáo, Tủa Chùa.","Tháng 6/1949, trong một trận càn lớn của Pháp, anh bị bắt khi đang làm nhiệm vụ, bị tra tấn dã man nhưng không khai. Chiều 15/6/1949, anh bị bắn chết gần đồn Bản Chăn khi chưa tròn 15 tuổi."],"src":"Những tấm gương anh hùng liệt sĩ của tuổi trẻ Việt Nam (Ban Tuyên giáo Tỉnh đoàn Bến Tre, 2014)"},{"id":"vs59-nguyenvietxuan","name":"Nguyễn Viết Xuân","period":"1934–1964","role":"Chính trị viên đại đội pháo cao xạ","nhom":"Anh hùng liệt sĩ tuổi trẻ","nam":1964,"bio":["Sinh năm 1934 ở Ngũ Kiên, Vĩnh Tường (Vĩnh Phúc), tuổi nhỏ phải đi ở suốt mười năm. Năm 1952, anh vượt vùng tạm chiếm ra vùng tự do nhập ngũ, từng chiến đấu ở chiến dịch Điện Biên Phủ.","Ngày 18/11/1964, máy bay Mĩ đánh phá vùng Cha Lo (miền tây Quảng Bình). Giữa làn bom đạn, anh đứng bên khẩu đội hô “Nhằm thẳng quân thù, bắn!”, câu hô về sau trở thành khẩu hiệu của bộ đội phòng không.","Bị thương nát đùi, anh bảo y tá cắt bỏ phần chân để khỏi vướng, giấu thương tích để đồng đội yên tâm chiến đấu, rồi bàn giao nhiệm vụ trước khi hi sinh. Năm 1967, anh được truy tặng Anh hùng Lực lượng vũ trang nhân dân."],"src":"Những tấm gương anh hùng liệt sĩ của tuổi trẻ Việt Nam (Ban Tuyên giáo Tỉnh đoàn Bến Tre, 2014)"},{"id":"vs59-truongdinh","name":"Trương Định","period":"1820–1864","role":"Lãnh tụ kháng Pháp ở Nam Kì","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Quảng Ngãi, theo gia đình vào Tân An (Long An) lập nghiệp, có công chiêu mộ dân khai hoang nên được cử làm Quản cơ đồn điền, quen gọi là Quản Định.","Năm 1859 Pháp đánh Gia Định, ông đưa nghĩa binh đồn điền ra trận, rồi lập đại đồn ở Tân Hòa (Gò Công). Khi triều đình kí hòa ước 1862 và ra lệnh bãi binh, ông ở lại cùng nhân dân chiến đấu, được tôn là Bình Tây Đại nguyên soái.","Ngày 20/8/1864, bị phản bội và bị bao vây, ông tự sát để không rơi vào tay giặc."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 135","trieu":"nguyenvn"},{"id":"vs59-nguyentrungtruc","name":"Nguyễn Trung Trực","period":"1838–1868","role":"Thủ lĩnh nghĩa quân Nam Kì","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Còn gọi là Nguyễn Văn Lịch (Quản Lịch), người phủ Tân An, vừa làm ruộng vừa đánh cá.","Trưa 10/12/1861, ông chỉ huy nghĩa quân đốt cháy tàu chiến Hi Vọng (Espérance) của Pháp trên sông Vàm Cỏ Đông ở vàm Nhật Tảo. Năm 1868, ông đánh úp đồn Kiên Giang, chiếm được đồn trong một thời gian.","Pháp bắt mẹ và dân lành để ép ông ra hàng; ông nộp mình và bị xử chém ở Rạch Giá năm 1868. Câu nói được truyền lại: bao giờ người Tây nhổ hết cỏ nước Nam mới hết người Nam đánh Tây."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 553","trieu":"nguyenvn"},{"id":"vs59-voduyduong","name":"Võ Duy Dương (Thiên hộ Dương)","period":"?–1866","role":"Thủ lĩnh kháng Pháp vùng Đồng Tháp Mười","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Được triều đình phong chức Thiên hộ nên gọi là Thiên hộ Dương; gốc tích chưa xác minh rõ.","Nghĩa binh của ông phối hợp với Trương Định hoạt động giữa sông Tiền và sông Vàm Cỏ. Sau khi Trương Định mất (1864), ông là thủ lĩnh chính của phong trào kháng chiến Nam Kì, lấy Đồng Tháp Mười làm căn cứ.","Năm 1866, căn cứ bị quân Pháp tấn công; ông rút đi và mất trong năm đó."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 117","trieu":"nguyenvn"},{"id":"vs59-nguyenhuuhuan","name":"Nguyễn Hữu Huân (Thủ khoa Huân)","period":"1813–1875","role":"Thủ lĩnh kháng Pháp ở Định Tường","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Định Tường (Tiền Giang), đỗ đầu kì thi Hương năm 1852 nên gọi là Thủ khoa Huân, làm giáo thụ ở huyện nhà.","Khi Pháp xâm lược Nam Kì, ông phối hợp với Võ Duy Dương, Âu Dương Lân đánh du kích từ Tân An đến Mỹ Tho. Ông bị bắt ba lần, mỗi lần được tha lại tập hợp lực lượng chiến đấu.","Năm 1875, ông bị bắt lần cuối và bị Pháp xử chém; trước khi mất còn làm thơ tỏ chí."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 202","trieu":"nguyenvn"},{"id":"vs59-nguyendinhchieu","name":"Nguyễn Đình Chiểu","period":"1822–1888","role":"Nhà thơ yêu nước Nam Kì","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Sinh ở Tân Thới, Gia Định, trong một gia đình nhà nho nghèo. Năm 1843 đỗ Tú tài; trên đường về chịu tang mẹ, ông bị đau mắt rồi mù, từ đó mở trường dạy học và làm thuốc.","Ông là tác giả truyện thơ Lục Vân Tiên và Văn tế nghĩa sĩ Cần Giuộc. Khi Pháp chiếm Nam Kì, ông dùng ngòi bút cổ vũ kháng chiến, kiên quyết không hợp tác với giặc.","Ông được coi là ngôi sao sáng của văn học yêu nước Việt Nam nửa sau thế kỉ XIX."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 72","trieu":"nguyenvn"},{"id":"vs59-phanthanhgian","name":"Phan Thanh Giản","period":"1796–1867","role":"Đại thần triều Nguyễn","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Vĩnh Long (nay thuộc Ba Tri, Bến Tre), đỗ Tiến sĩ đầu tiên của Nam Kì (1826), làm quan qua ba triều Minh Mạng, Thiệu Trị, Tự Đức, nổi tiếng thanh liêm.","Ông cùng Lâm Duy Hiệp thay mặt triều đình kí Hòa ước 5/6/1862 nhượng ba tỉnh miền Đông Nam Kì, sau sang Pháp xin chuộc lại nhưng không thành.","Năm 1867, khi làm Kinh lược sứ ba tỉnh miền Tây, trước sức ép của Pháp ông giao thành rồi uống thuốc độc tự vẫn. Đánh giá về ông còn có nhiều ý kiến khác nhau."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 152","trieu":"nguyenvn"},{"id":"vs59-hoangkeviem","name":"Hoàng Kế Viêm","period":"1820–1909","role":"Tướng triều Nguyễn chống Pháp ở Bắc Kì","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Còn gọi là Hoàng Tá Viêm, quê Quảng Bình, đỗ Cử nhân năm 1843 và làm quan nhiều đời vua.","Năm 1870 ông dẹp các toán phỉ ở biên giới phía bắc và thu phục tướng Cờ đen Lưu Vĩnh Phúc. Khi Pháp đánh Bắc Kì (1873, 1882), quân của ông phối hợp quân Cờ đen thắng hai trận lớn ở Cầu Giấy.","Năm 1885 ông nhận lệnh triều đình Đồng Khánh đi chiêu dụ nghĩa quân Cần vương, việc làm khiến ông bị dư luận đương thời phê phán."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 594","trieu":"nguyenvn"},{"id":"vs59-nguyenquangbich","name":"Nguyễn Quang Bích","period":"1832–1890","role":"Lãnh tụ Cần vương ở Tây Bắc","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Tiền Hải (Thái Bình), đỗ Đình nguyên Hoàng giáp năm 1869. Năm 1883 làm Tuần phủ Hưng Hóa, ông chỉ huy giữ thành chống Pháp.","Khi thành mất, ông không theo lệnh bãi binh của triều đình mà rút lên Tây Bắc lập căn cứ. Năm 1885 hưởng ứng chiếu Cần vương, ông được vua Hàm Nghi phong Hiệp thống quân vụ đại thần.","Ông lãnh đạo kháng chiến ở vùng Tây Bắc cho đến khi mất vì bệnh năm 1890."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 30","trieu":"nguyenvn"},{"id":"vs59-nguyenthienthuat","name":"Nguyễn Thiện Thuật (Tán Thuật)","period":"1844–1926","role":"Lãnh tụ khởi nghĩa Bãi Sậy","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Người Mỹ Hào (Hưng Yên), đỗ Cử nhân năm 1876, từng làm Tán tương quân vụ Hải Dương nên gọi là Tán Thuật.","Năm 1882 ông mộ quân đánh Pháp; năm 1885 hưởng ứng chiếu Cần vương, thống nhất lực lượng ở vùng bãi sậy Hưng Yên – Hải Dương, mở cuộc khởi nghĩa Bãi Sậy.","Năm 1889 phong trào bị đàn áp, ông sang Trung Quốc và mất ở đó năm 1926."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 501","trieu":"nguyenvn"},{"id":"vs59-dinhcongtrang","name":"Đinh Công Tráng","period":"1842–1887","role":"Chỉ huy khởi nghĩa Ba Đình","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Người Thanh Liêm (Hà Nam), từng là chánh tổng; tham gia quân Hoàng Kế Viêm và trận đánh tại Cầu Giấy ngày 19/5/1883.","Hưởng ứng Cần vương, ông cùng Phạm Bành, Hoàng Bật Đạt xây dựng cứ điểm Ba Đình (Nga Sơn, Thanh Hóa) và là chỉ huy quân sự chính, cầm cự với quân Pháp từ cuối 1886 đến đầu 1887.","Ba Đình thất thủ, ông rút về Nghệ An và hi sinh năm 1887."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 535","trieu":"nguyenvn"},{"id":"vs59-phambanh","name":"Phạm Bành","period":"1827–1887","role":"Thủ lĩnh khởi nghĩa Ba Đình","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Người Hậu Lộc (Thanh Hóa), đỗ Cử nhân năm 1864, làm đến Án sát Nghệ An, nổi tiếng thanh liêm.","Năm 1885, khi đã gần 60 tuổi, ông cùng Đinh Công Tráng, Hoàng Bật Đạt dựng cứ điểm Ba Đình gồm ba làng Mỹ Khê, Thượng Thọ, Mậu Thịnh.","Sau khi Ba Đình thất thủ, Pháp bắt mẹ và con ông để ép ra hàng; ông tự vẫn năm 1887."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 22","trieu":"nguyenvn"},{"id":"vs59-nguyenduyhieu","name":"Nguyễn Duy Hiệu","period":"1847–1887","role":"Lãnh tụ Nghĩa hội Quảng Nam","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Điện Bàn (Quảng Nam), đỗ Phó bảng năm 1879, từng dạy hoàng tử Ưng Đăng (vua Kiến Phúc).","Khi triều đình kí hiệp ước với Pháp, ông từ quan về lập nghĩa hội; năm 1885 hưởng ứng Cần vương, ông lãnh đạo Nghĩa hội Quảng Nam, lập căn cứ Trung Lộc.","Năm 1887 ông bị bắt và bị xử chém ở Huế, giữ trọn khí tiết."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 182","trieu":"nguyenvn"},{"id":"vs59-maixuanthuong","name":"Mai Xuân Thưởng","period":"1860–1887","role":"Thủ lĩnh Cần vương ở Bình Định","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Phú Lạc, huyện Tây Sơn (Bình Định), đỗ Cử nhân ở trường thi Bình Định.","Năm 1885 hưởng ứng chiếu Cần vương, ông chiêu mộ nghĩa quân, trở thành thủ lĩnh phong trào ở Bình Định, Phú Yên.","Năm 1887 ông bị bắt và bị hành hình, nhưng phong trào đã gây cho quân Pháp nhiều khó khăn."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 511","trieu":"nguyenvn"},{"id":"vs59-caothang","name":"Cao Thắng","period":"1864–1893","role":"Tướng của khởi nghĩa Hương Khê","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Người Hương Sơn (Hà Tĩnh), nhà nghèo nhưng giỏi cả văn lẫn võ.","Cuối năm 1885, ông cùng em là Cao Nữu đưa lực lượng theo Phan Đình Phùng, trở thành tướng chủ chốt của khởi nghĩa Hương Khê. Ông cho chế tạo được súng trường theo mẫu súng Pháp.","Năm 1893, ông hi sinh khi chỉ huy tấn công đồn Nu (Thanh Chương, Nghệ An)."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 471","trieu":"nguyenvn"},{"id":"vs59-hoanghoatham","name":"Hoàng Hoa Thám (Đề Thám)","period":"1858–1913","role":"Thủ lĩnh khởi nghĩa Yên Thế","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Gốc Tiên Lữ (Hưng Yên), lớn lên ở Yên Thế (Bắc Giang). Từ năm 1885 ông tham gia các toán nghĩa quân chống Pháp ở Yên Thế, sau trở thành thủ lĩnh, quen gọi là Đề Thám.","Nghĩa quân Yên Thế dựa vào rừng núi, đánh du kích suốt gần ba mươi năm, hai lần buộc Pháp phải giảng hòa (1894, 1897). Ông còn liên hệ với Phan Bội Châu và các nhà yêu nước đầu thế kỉ XX.","Năm 1913, ông bị tay sai của Pháp ám hại; cuộc khởi nghĩa chấm dứt."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 456","trieu":"nguyenvn"},{"id":"vs59-nguyentruongto","name":"Nguyễn Trường Tộ","period":"1830–1871","role":"Nhà cải cách","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Hưng Nguyên (Nghệ An), xuất thân gia đình Công giáo nghèo, học rộng cả Hán học lẫn khoa học phương Tây.","Từ năm 1863 đến 1871, ông gửi lên triều đình nhiều bản điều trần đề nghị canh tân: mở rộng ngoại giao, chấn hưng kinh tế, cải cách giáo dục, quân sự.","Các đề nghị phần lớn không được thực hiện. Ông mất năm 1871 khi mới 41 tuổi."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 526","trieu":"nguyenvn"},{"id":"vs59-phamphutho","name":"Phạm Phú Thứ","period":"1820–1880","role":"Đại thần chủ trương canh tân","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Diên Phước (Quảng Nam), đỗ Hội nguyên Tiến sĩ năm 1843, giữ nhiều chức vụ quan trọng.","Năm 1863 ông là phó sứ trong phái đoàn Phan Thanh Giản sang Pháp, sau đó viết sách giới thiệu những điều tai nghe mắt thấy ở phương Tây và đề nghị cải cách.","Ông chú ý mở mang giao thương, khai mỏ, nhưng triều đình không áp dụng rộng rãi."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 506","trieu":"nguyenvn"},{"id":"vs59-tranvandu","name":"Trần Văn Dư","period":"1839–1885","role":"Thủ lĩnh Cần vương Quảng Nam","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Tam Kỳ (Quảng Nam), đỗ Tiến sĩ năm 1875, từng dạy học cho Ưng Chân (vua Dục Đức) và Ưng Kỷ (vua Đồng Khánh).","Năm 1885 hưởng ứng chiếu Cần vương, ông đứng đầu Nghĩa hội Quảng Nam, tấn công tỉnh thành La Qua.","Cuối năm 1885 ông bị bắt và bị xử tử; Nguyễn Duy Hiệu tiếp tục lãnh đạo nghĩa hội."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 114","trieu":"nguyenvn"},{"id":"vs59-tongduytan","name":"Tống Duy Tân","period":"1837–1892","role":"Thủ lĩnh khởi nghĩa Hùng Lĩnh","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Người Vĩnh Lộc (Thanh Hóa), đỗ Tiến sĩ năm 1875, làm Tri phủ Vĩnh Tường hai năm rồi cáo quan về dạy học vì bất bình với triều đình.","Theo yêu cầu của Tôn Thất Thuyết, ông cùng Cao Điển lãnh đạo khởi nghĩa Hùng Lĩnh (Thanh Hóa), tiếp nối phong trào sau khi Ba Đình thất thủ.","Năm 1892 ông bị bắt do bị phản bội và bị xử chém."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 442","trieu":"nguyenvn"},{"id":"vs59-trantan","name":"Trần Tấn","period":"?–1874","role":"Lãnh tụ phong trào Bình Tây sát tả","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Thanh Chương (Nghệ An), đỗ Tú tài, về quê dạy học; kiên quyết phản đối việc cắt đất cầu hòa.","Năm 1874, ông cùng học trò Đặng Như Mai phát động phong trào Bình Tây sát tả ở Nghệ Tĩnh, chống Pháp và chống triều đình thỏa hiệp.","Phong trào bị đàn áp; ông mất vì bệnh trong năm đó."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 446","trieu":"nguyenvn"},{"id":"vs59-dangnhumai","name":"Đặng Như Mai","period":"?–1874","role":"Văn thân Nghệ An","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Nam Đàn (Nghệ An), dạy học ở Thanh Chương, là học trò của Trần Tấn, đỗ Tú tài năm 1848.","Năm 1874, ông cùng Trần Tấn lãnh đạo phong trào Bình Tây sát tả, kêu gọi đánh Pháp và chống những kẻ đầu hàng.","Phong trào thất bại, ông bị bắt và bị xử tử năm 1874."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 318","trieu":"nguyenvn"},{"id":"vs59-letrungdinh","name":"Lê Trung Đình","period":"1863–1885","role":"Thủ lĩnh Cần vương Quảng Ngãi","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Người Bình Sơn (Quảng Ngãi), đỗ Cử nhân năm 1884 nhưng không ra làm quan.","Năm 1885, hưởng ứng chiếu Cần vương, ông cùng các sĩ phu Quảng Ngãi đánh chiếm tỉnh thành.","Chỉ ít ngày sau ông bị bắt và bị xử chém khi mới 22 tuổi."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 131","trieu":"nguyenvn"},{"id":"vs59-nguyenxuanon","name":"Nguyễn Xuân Ôn","period":"1825–1889","role":"Lãnh tụ Cần vương Nghệ An","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Người Diễn Châu (Nghệ An), đỗ Tiến sĩ, làm quan nhưng nhiều lần dâng sớ đòi chống Pháp nên bị cách chức.","Năm 1885, ông lãnh đạo phong trào Cần vương ở Diễn Châu, Yên Thành, được phong Tán tương quân vụ.","Năm 1887 ông bị bắt, bị đưa về Huế an trí và mất năm 1889. Ông còn để lại nhiều thơ văn yêu nước."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 377","trieu":"nguyenvn"},{"id":"vs59-nguyenvantuong","name":"Nguyễn Văn Tường","period":"1824–1886","role":"Phụ chính đại thần triều Nguyễn","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Triệu Phong (Quảng Trị), đỗ Cử nhân, giữ nhiều chức vụ quan trọng thời Tự Đức.","Sau khi Tự Đức mất (1883), ông cùng Tôn Thất Thuyết làm phụ chính, phế lập liên tiếp nhiều vua. Năm 1885 ông tham gia cuộc phản công kinh thành Huế nhưng sau đó ở lại thương thuyết với Pháp.","Ông bị Pháp bắt, đày ra đảo Tahiti và mất ở đó năm 1886."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 582","trieu":"nguyenvn"},{"id":"vs59-levankhoi","name":"Lê Văn Khôi","period":"?–1834","role":"Thủ lĩnh cuộc nổi dậy ở Gia Định","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Tên thật Nguyễn Hữu Khôi, thổ hào Cao Bằng, được Lê Văn Duyệt nhận làm con nuôi và đưa vào Nam.","Năm 1833, bất bình vì Lê Văn Duyệt bị triều đình truy tội, ông chiếm thành Phiên An (Gia Định), làm chủ Nam Kì một thời gian.","Ông mất năm 1834 trong thành; đến năm 1835 quân triều đình mới hạ được thành."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 246","trieu":"nguyenvn"},{"id":"vs59-nongvanvan","name":"Nông Văn Vân","period":"?–1835","role":"Thủ lĩnh khởi nghĩa ở Cao Bằng","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Người Tày, Tri châu Bảo Lạc (Cao Bằng).","Năm 1833, ông nổi dậy chống triều Minh Mạng, nghĩa quân chiếm nhiều vùng ở Cao Bằng, Thái Nguyên, Tuyên Quang, ảnh hưởng đến Lạng Sơn, Quảng Ninh.","Tháng 3/1835, khởi nghĩa bị dập tắt, ông chết trong rừng."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 592","trieu":"nguyenvn"},{"id":"vs59-nguyenvanthoai","name":"Nguyễn Văn Thoại (Thoại Ngọc Hầu)","period":"1762–1829","role":"Người chỉ huy đào kênh Vĩnh Tế","nhom":"Thời Nguyễn – kháng Pháp thế kỉ XIX","bio":["Quê Quảng Nam, theo Nguyễn Ánh từ sớm, sau làm Trấn thủ Lạng Sơn, Định Tường, tước Thoại Ngọc Hầu.","Ông chỉ huy đào sông Thoại Hà (1818) và kênh Vĩnh Tế (1819–1824) nối Châu Đốc với Hà Tiên, có ý nghĩa lớn về giao thông, khai hoang và giữ biên giới Tây Nam.","Vua Minh Mạng lấy tên vợ ông là Châu Thị Vĩnh Tế đặt tên cho con kênh."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 492","trieu":"nguyenvn"},{"id":"vs59-caobaquat","name":"Cao Bá Quát","period":"1808–1855","role":"Nhà thơ, thủ lĩnh khởi nghĩa Mỹ Lương","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Tự Chu Thần, quê Phú Thụy, Gia Lâm (Hà Nội), nổi tiếng “văn hay chữ tốt”, đỗ Cử nhân năm 1831.","Ông làm quan nhỏ, có thời bị tù vì sửa bài thi cho thí sinh. Bất mãn với triều đình, năm 1854 ông cùng nông dân nổi dậy ở Mỹ Lương (Sơn Tây) trong lúc nạn châu chấu, đói kém.","Ông tử trận năm 1855. Thơ văn ông thể hiện tư tưởng phóng khoáng, phê phán xã hội đương thời."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 409","trieu":"nguyenvn"},{"id":"vs59-nguyenkhuyen","name":"Nguyễn Khuyến","period":"1835–1909","role":"Nhà thơ (Tam nguyên Yên Đổ)","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Hiệu Quế Sơn, quê Yên Đổ, Bình Lục (Hà Nam). Ông đỗ đầu cả ba kì thi Hương, Hội, Đình nên gọi là Tam nguyên Yên Đổ.","Làm quan một thời gian rồi cáo về khi Pháp chiếm Bắc Kì, không chịu hợp tác với chính quyền mới.","Thơ ông viết về làng quê Bắc Bộ (chùm thơ thu) và châm biếm thói đời, giàu tình yêu nước kín đáo."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 250","trieu":"nguyenvn"},{"id":"vs59-trantexuong","name":"Trần Tế Xương (Tú Xương)","period":"1870–1907","role":"Nhà thơ trào phúng","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Tên thật Trần Duy Uyên, quê Vị Xuyên, Nam Định; đỗ Tú tài năm 1894 nên gọi là Tú Xương, nhiều lần thi Cử nhân không đỗ.","Thơ ông châm biếm sắc sảo cảnh “nửa Tây nửa ta” của xã hội thực dân nửa phong kiến buổi giao thời.","Ông mất năm 1907 khi mới 37 tuổi, để lại nhiều bài thơ Nôm nổi tiếng."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 609","trieu":"nguyenvn"},{"id":"vs59-truongvinhky","name":"Trương Vĩnh Ký","period":"1837–1898","role":"Học giả, nhà ngôn ngữ học","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Quê Cái Mơn (nay thuộc Bến Tre), học ở trong nước và nước ngoài, thông thạo nhiều thứ tiếng Đông – Tây.","Ông làm phiên dịch cho chính quyền Pháp ở Nam Kì, chủ bút Gia Định báo (tờ báo chữ Quốc ngữ đầu tiên) và biên soạn hơn một trăm cuốn sách về ngôn ngữ, văn học, lịch sử.","Đóng góp về học thuật của ông được ghi nhận, còn việc ông cộng tác với Pháp có nhiều ý kiến đánh giá khác nhau."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 266","trieu":"nguyenvn"},{"id":"vs59-phanhuychu","name":"Phan Huy Chú","period":"1782–1840","role":"Nhà bác học, tác giả Lịch triều hiến chương loại chí","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Hiệu Mai Phong, con Phan Huy Ích, quê làng Thầy (Quốc Oai, Hà Nội).","Ông dành gần mười năm biên soạn bộ Lịch triều hiến chương loại chí, bộ bách khoa về địa lí, nhân vật, quan chức, lễ nghi, khoa cử, binh chế, văn tịch… của các triều đại Việt Nam.","Ông được triều Minh Mạng dùng làm quan, từng đi sứ Trung Quốc, In-đô-nê-xi-a; về cuối đời lui về dạy học."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 78","trieu":"nguyenvn"},{"id":"vs59-trinhhoaiduc","name":"Trịnh Hoài Đức","period":"1765–1825","role":"Nhà văn, nhà sử – địa học","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Tự Chỉ Sơn, gốc người Hoa, lập nghiệp ở Trấn Biên (Biên Hòa). Năm 1788 ông theo Nguyễn Ánh, sau giữ nhiều chức lớn như Hiệp tổng trấn Gia Định thành.","Ông là tác giả Gia Định thành thông chí, bộ địa chí quý về vùng đất Nam Bộ, và là một trong “Gia Định tam gia” về thơ.","Ông từng đi sứ nhà Thanh và giữ chức Thượng thư nhiều bộ dưới triều Gia Long, Minh Mạng."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 146","trieu":"nguyenvn"},{"id":"vs59-hoxuanhuong","name":"Hồ Xuân Hương","period":"cuối thế kỉ XVIII – đầu XIX","role":"Nữ sĩ","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Quê gốc Quỳnh Đôi (Nghệ An), cha là nhà nho ra Bắc dạy học; năm sinh, năm mất của bà chưa rõ.","Bà nổi tiếng với thơ Nôm táo bạo, thông minh, đề cao vẻ đẹp và khát vọng của người phụ nữ, chế giễu thói đạo đức giả.","Bà được gọi là “Bà chúa thơ Nôm”."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 217"},{"id":"vs59-bahuyenthanhquan","name":"Bà Huyện Thanh Quan","period":"đầu thế kỉ XIX","role":"Nữ sĩ","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Tên thật Nguyễn Thị Hinh, người Nghi Tàm (Tây Hồ, Hà Nội), con nhà nho; chồng làm tri huyện Thanh Quan nên gọi là Bà Huyện Thanh Quan.","Bà từng được vua Minh Mạng mời vào cung làm Cung trung giáo tập, dạy các cung nữ.","Thơ bà trang nhã, hoài cổ, tiêu biểu là Qua Đèo Ngang, Thăng Long thành hoài cổ."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 184","trieu":"nguyenvn"},{"id":"vs59-doanthidiem","name":"Đoàn Thị Điểm","period":"1705–1748","role":"Nữ sĩ","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Hiệu Hồng Hà nữ sĩ, quê Giai Phạm, Văn Giang (Hưng Yên), con nhà nho.","Bà nổi tiếng học giỏi, từng dạy học; được nhiều người cho là dịch giả bản Chinh phụ ngâm chữ Nôm từ nguyên tác chữ Hán của Đặng Trần Côn.","Bà còn viết tập truyện chữ Hán Truyền kì tân phả."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 129","trieu":"letrung"},{"id":"vs59-nguyengiathieu","name":"Nguyễn Gia Thiều","period":"1741–1798","role":"Nhà thơ, tác giả Cung oán ngâm khúc","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Người Thuận Thành (Bắc Ninh), mẹ là quận chúa con chúa Trịnh Cương; học rộng, giỏi âm nhạc, hội họa, kiến trúc.","Ông làm võ quan dưới thời Lê – Trịnh, tước Ôn Như hầu.","Tác phẩm Cung oán ngâm khúc nói nỗi oán hận của người cung nữ bị ruồng bỏ, là kiệt tác của thể song thất lục bát."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 487","trieu":"letrung"},{"id":"vs59-phanhuyich","name":"Phan Huy Ích","period":"1751–1822","role":"Văn thần triều Tây Sơn","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Hiệu Dụ Am, quê Thạch Hà (Hà Tĩnh), học trò và con rể Ngô Thì Sĩ; đỗ Tiến sĩ năm 1775.","Ông ra giúp triều Tây Sơn, phụ trách nhiều việc ngoại giao với nhà Thanh, từng đi sứ Bắc Kinh năm 1790.","Ông để lại nhiều thơ văn; con ông là nhà bác học Phan Huy Chú."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 222","trieu":"tayson"},{"id":"vs59-nguyenhuucau","name":"Nguyễn Hữu Cầu (Quận He)","period":"?–1751","role":"Thủ lĩnh khởi nghĩa nông dân Đàng Ngoài","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Người Thanh Hà (Hải Dương), xuất thân nông dân nghèo, giỏi võ, bơi lội.","Từ năm 1741, ông lãnh đạo cuộc khởi nghĩa lớn ở vùng Hải Dương, Sơn Nam, Kinh Bắc, khẩu hiệu lấy của nhà giàu chia cho người nghèo, nhiều lần đánh bại quân chúa Trịnh.","Năm 1751, ông bị bắt và bị xử tử."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 55","trieu":"letrung"},{"id":"vs59-hoangcongchat","name":"Hoàng Công Chất","period":"?–1768","role":"Thủ lĩnh khởi nghĩa nông dân","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Quê Hưng Yên (có tài liệu ghi Hà Tây hoặc Thái Bình); cuối năm 1739 nổi dậy hưởng ứng phong trào nông dân Đàng Ngoài.","Sau ông đưa nghĩa quân lên Tây Bắc, xây dựng căn cứ Mường Thanh (Điện Biên), đánh đuổi quân Phổ Phong từ Vân Nam sang quấy phá.","Ông giữ vùng này gần ba mươi năm; sau khi ông mất, căn cứ bị quân Trịnh đánh tan."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 62","trieu":"letrung"},{"id":"vs59-lengochan","name":"Lê Ngọc Hân","period":"1770–1799","role":"Công chúa, Bắc cung hoàng hậu","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Con gái vua Lê Hiển Tông. Năm 1786, khi Nguyễn Huệ ra Bắc, vua Lê gả bà cho ông; năm 1788 bà được phong Bắc cung hoàng hậu.","Sau khi Quang Trung mất (1792), bà viết Ai tư vãn bày tỏ niềm thương nhớ.","Bà mất năm 1799."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 172","trieu":"tayson"},{"id":"vs59-nguyenhuuchinh","name":"Nguyễn Hữu Chỉnh","period":"?–1787","role":"Tướng cuối thời Lê – Trịnh","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Quê Nghi Lộc (Nghệ An), đỗ Hương cống năm 16 tuổi nên gọi là Cống Chỉnh, giỏi cả văn võ.","Ông từng phục vụ họ Trịnh, sau theo Tây Sơn ra Bắc năm 1786, rồi quay sang phò vua Lê Chiêu Thống, chuyên quyền ở Bắc Hà.","Năm 1787, Nguyễn Huệ sai Vũ Văn Nhậm ra đánh; Chỉnh thua và bị giết."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 75","trieu":"letrung"},{"id":"vs59-maccuu","name":"Mạc Cửu","period":"1655–1735","role":"Người khai phá Hà Tiên","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Gốc Lôi Châu (Quảng Đông), không thần phục nhà Thanh nên đưa gia đình sang phương Nam.","Ông chiêu tập dân khai phá vùng ven biển, lập nên đất Hà Tiên. Năm 1708 ông xin thần thuộc chúa Nguyễn, được phong Tổng binh trấn Hà Tiên.","Vùng Hà Tiên từ đó thuộc về Đàng Trong."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 91","trieu":"letrung"},{"id":"vs59-macthientich","name":"Mạc Thiên Tích","period":"1706–1780","role":"Tổng binh Hà Tiên, nhà thơ","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Con Mạc Cửu, nối cha giữ trấn Hà Tiên, xây dựng nơi đây thành vùng buôn bán sầm uất.","Ông lập Chiêu Anh Các, nơi hội họp văn nhân, để lại tập Hà Tiên thập vịnh.","Cuối đời, trong biến động với Xiêm và Tây Sơn, ông sang Xiêm và mất ở đó năm 1780."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 512","trieu":"letrung"},{"id":"vs59-nguyencutrinh","name":"Nguyễn Cư Trinh","period":"1716–1767","role":"Nhà văn, nhà chính trị Đàng Trong","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Hiệu Đạm Am, gốc Nghệ An, sau vào Thuận Hóa. Ông làm Tuần phủ Quảng Ngãi, rồi được giao kinh lược vùng đất phía nam.","Ông góp phần lớn vào việc mở rộng, ổn định vùng đất Nam Bộ thời chúa Nguyễn Phúc Khoát.","Ông để lại tác phẩm Sãi vãi viết bằng chữ Nôm."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 541","trieu":"letrung"},{"id":"vs59-nguyenhuucanh","name":"Nguyễn Hữu Cảnh","period":"1650–1700","role":"Danh tướng chúa Nguyễn, người lập phủ Gia Định","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Còn gọi Nguyễn Hữu Kính, con thứ của Chiêu Vũ hầu Nguyễn Hữu Dật, tổ tiên ở Tống Sơn (Thanh Hóa).","Năm 1698, ông được chúa Nguyễn Phúc Chu cử vào kinh lược đất Đồng Nai, lập phủ Gia Định với hai dinh Trấn Biên, Phiên Trấn, đặt quan cai trị, lập sổ bộ dân cư.","Ông mất năm 1700 trên đường trở về sau khi đem quân lên vùng biên giới phía tây."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 45","trieu":"letrung"},{"id":"vs59-ngovanso","name":"Ngô Văn Sở","period":"?–1795","role":"Danh tướng Tây Sơn","nhom":"Văn hóa – khai phá thế kỉ XVIII–XIX","bio":["Gốc Can Lộc (Hà Tĩnh), sau vào Bình Khê (Bình Định), học võ với Ngô Mạnh.","Cuối năm 1788, khi quân Thanh kéo sang, ông là tướng trấn giữ Bắc Hà; theo kế của Ngô Thì Nhậm, ông rút quân về giữ phòng tuyến Tam Điệp – Biện Sơn để bảo toàn lực lượng.","Ông tham gia cuộc đại phá quân Thanh mùa xuân 1789 cùng vua Quang Trung."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 431","trieu":"tayson"},{"id":"vs59-phanchautrinh","name":"Phan Châu Trinh","period":"1872–1926","role":"Chí sĩ, lãnh tụ phong trào Duy tân","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Hiệu Tây Hồ, quê Tiên Phước (Quảng Nam), đỗ Phó bảng năm 1901, làm quan ít lâu rồi từ chức.","Ông chủ trương “khai dân trí, chấn dân khí, hậu dân sinh”, cổ động mở trường, mở mang công thương, bỏ lối học cũ. Năm 1908 ông bị bắt vì phong trào chống thuế, bị đày ra Côn Đảo.","Ông sang Pháp năm 1911, tiếp tục viết bài đòi cải cách. Về nước năm 1925 và mất ở Sài Gòn năm 1926; đám tang ông trở thành cuộc vận động yêu nước rộng lớn."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 542","trieu":"nguyenvn"},{"id":"vs59-luongvancan","name":"Lương Văn Can","period":"1854–1927","role":"Thục trưởng Đông Kinh nghĩa thục","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Quê Nhị Khê, Thường Tín (Hà Nội), đỗ Cử nhân năm 21 tuổi nên gọi là Cử Can, mở trường dạy học ở phố Hàng Đào.","Năm 1907, ông cùng các sĩ phu lập Đông Kinh nghĩa thục và làm thục trưởng, dạy học miễn phí theo lối mới, cổ động thực nghiệp.","Năm 1913 ông bị Pháp bắt, đày sang Nam Vang (Campuchia). Con ông là Lương Ngọc Quyến."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 43","trieu":"nguyenvn"},{"id":"vs59-nguyenthuonghien","name":"Nguyễn Thượng Hiền","period":"1868–1925","role":"Nhà yêu nước, nhà thơ","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Hiệu Mai Sơn, quê Ứng Hòa (Hà Nội), đỗ Hoàng giáp năm 1889, làm quan một thời gian.","Ông bỏ quan, xuất dương sang Trung Quốc, Nhật Bản, tham gia phong trào Đông Du và Việt Nam Quang phục hội.","Ông mất ở Trung Quốc năm 1925, để lại nhiều thơ văn yêu nước."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 174","trieu":"nguyenvn"},{"id":"vs59-dangthaithan","name":"Đặng Thái Thân","period":"1873–1910","role":"Nhà yêu nước, đồng chí của Phan Bội Châu","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Hiệu Ngư Hải, quê Nghi Lộc (Nghệ An), học trò và đồng chí của Phan Bội Châu.","Năm 1904 ông cùng Phan Bội Châu lập Hội Duy Tân, phụ trách việc đưa thanh niên xuất dương và tổ chức lực lượng trong nước.","Năm 1910, bị quân Pháp vây bắt, ông tự sát để giữ bí mật cho tổ chức."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 475","trieu":"nguyenvn"},{"id":"vs59-ngoducke","name":"Ngô Đức Kế","period":"1879–1929","role":"Nhà yêu nước, nhà báo","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Hiệu Tập Xuyên, quê Can Lộc (Hà Tĩnh), đỗ Tiến sĩ năm 1901 nhưng không ra làm quan.","Ông tham gia phong trào Duy tân, lập hội buôn; năm 1908 bị bắt, đày ra Côn Đảo.","Ra tù, ông làm chủ bút báo Hữu Thanh, viết nhiều bài phê phán khuynh hướng văn chương xa rời thực tế."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 224","trieu":"nguyenvn"},{"id":"vs59-tranquycap","name":"Trần Quý Cáp","period":"1870–1908","role":"Nhà yêu nước, phong trào Duy tân","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Quê Điện Bàn (Quảng Nam), đỗ Tiến sĩ năm 1904; cùng Phan Châu Trinh, Huỳnh Thúc Kháng cổ động duy tân ở Quảng Nam.","Ông phê phán lối học khoa cử, đề xướng học mới, mở trường; làm giáo thụ ở Thăng Bình, Diên Khánh, nơi nào cũng thành trung tâm truyền bá tư tưởng mới.","Năm 1908, khi phong trào chống thuế nổ ra, ông bị khép tội mưu phản và bị xử chém ngang lưng ở Khánh Hòa."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 49","trieu":"nguyenvn"},{"id":"vs59-thaiphien","name":"Thái Phiên","period":"1882–1916","role":"Lãnh đạo Việt Nam Quang phục hội ở Trung Kì","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Quê Hòa Vang (Đà Nẵng), một trong những người tân học đầu tiên tham gia phong trào yêu nước ở Quảng Nam.","Năm 1906 ông vận động cho phong trào Đông Du; năm 1916 cùng Trần Cao Vân tổ chức cuộc khởi nghĩa của vua Duy Tân.","Kế hoạch bị lộ, ông bị bắt và bị xử chém cùng Trần Cao Vân năm 1916."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 390","trieu":"nguyenvn"},{"id":"vs59-trancaovan","name":"Trần Cao Vân","period":"1866–1916","role":"Nhà yêu nước, cùng vua Duy Tân mưu khởi nghĩa","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Quê Điện Bàn (Quảng Nam), học vấn uyên thâm, sớm tham gia Nghĩa hội Quảng Nam của Nguyễn Duy Hiệu.","Ông nhiều lần bị bắt và tù đày. Năm 1916, cùng Thái Phiên liên lạc với vua Duy Tân chuẩn bị khởi nghĩa ở Trung Kì.","Cuộc khởi nghĩa bị lộ, ông bị bắt và bị xử chém năm 1916."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 593","trieu":"nguyenvn"},{"id":"vs59-luongngocquyen","name":"Lương Ngọc Quyến","period":"1885–1917","role":"Lãnh đạo khởi nghĩa Thái Nguyên","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Thường gọi Ba Quyến, con Lương Văn Can. Ông sang Nhật học quân sự theo phong trào Đông Du, rồi hoạt động ở Trung Quốc.","Năm 1915 bị bắt, giam ở nhà lao Thái Nguyên. Đêm 30/8/1917, ông cùng Đội Cấn lãnh đạo binh lính khố xanh nổi dậy, chiếm tỉnh lị Thái Nguyên.","Ông hi sinh ngay trong những ngày đầu của cuộc khởi nghĩa."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 414","trieu":"nguyenvn"},{"id":"vs59-trinhvancan","name":"Trịnh Văn Cấn (Đội Cấn)","period":"?–1918","role":"Thủ lĩnh khởi nghĩa binh lính Thái Nguyên","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Tên thật Trịnh Văn Đạt, quê Vĩnh Tường (Vĩnh Phúc), đội trưởng lính khố xanh nên gọi là Đội Cấn.","Ông cùng Lương Ngọc Quyến lãnh đạo khởi nghĩa Thái Nguyên (8/1917), làm chủ tỉnh lị gần một tuần, lập chính quyền và kêu gọi nhân dân chống Pháp.","Sau khi Thái Nguyên bị chiếm lại, ông rút vào rừng chiến đấu đến đầu năm 1918 rồi tự sát."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 54","trieu":"nguyenvn"},{"id":"vs59-cuongde","name":"Cường Để","period":"1882–1951","role":"Hội chủ Duy Tân hội","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Hoàng thân dòng dõi Hoàng tử Cảnh (con trưởng vua Gia Long), tước Kỳ Ngoại hầu.","Năm 1904 ông được Phan Bội Châu tôn làm Hội chủ Duy Tân hội; năm 1906 xuất dương sang Nhật.","Ông sống lưu vong phần lớn cuộc đời ở Nhật Bản và mất ở Tô-ki-ô năm 1951."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 90","trieu":"nguyenvn"},{"id":"vs59-nguyenthaihoc","name":"Nguyễn Thái Học","period":"1904–1930","role":"Lãnh tụ Việt Nam Quốc dân đảng","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Quê Thổ Tang, Vĩnh Tường (Vĩnh Phúc), từng học Trường Sư phạm và Cao đẳng Thương mại Hà Nội.","Cuối năm 1927 ông cùng các đồng chí thành lập Việt Nam Quốc dân đảng và làm Đảng trưởng.","Ông lãnh đạo khởi nghĩa Yên Bái (2/1930). Khởi nghĩa thất bại, ông bị bắt và bị xử chém ở Yên Bái ngày 17/6/1930."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 194","trieu":"nguyenvn"},{"id":"vs59-phamhongthai","name":"Phạm Hồng Thái","period":"1895–1924","role":"Liệt sĩ, người ném bom Sa Diện","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Sinh ngày 14/5/1895 ở Hưng Nguyên (Nghệ An), từng làm công nhân nhà máy xe lửa Trường Thi, nhà máy đèn Bến Thủy.","Sang Trung Quốc, ông tham gia tổ chức Tâm Tâm xã. Ngày 19/6/1924, ông ném bom ám sát Toàn quyền Đông Dương Méc-lanh ở khách sạn tại Sa Diện (Quảng Châu).","Việc không thành, bị truy đuổi, ông nhảy xuống sông Châu Giang hi sinh. Tiếng bom Sa Diện được ví như “chim én nhỏ báo hiệu mùa xuân”."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 454","trieu":"nguyenvn"},{"id":"vs59-nguyenanninh","name":"Nguyễn An Ninh","period":"1900–1943","role":"Nhà yêu nước, nhà báo Nam Kì","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Sinh ở Hóc Môn (Gia Định), con nhà nho yêu nước Nguyễn An Khương; đỗ Cử nhân Luật ở Pháp năm 1920.","Về nước, ông ra báo La Cloche fêlée (Chuông rè), diễn thuyết kêu gọi thanh niên, nhiều lần bị bắt giam.","Ông mất ở nhà tù Côn Đảo năm 1943."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 371","trieu":"nguyenvn"},{"id":"vs59-nguyenvanvinh","name":"Nguyễn Văn Vĩnh","period":"1882–1936","role":"Nhà báo, dịch giả","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Quê Thường Tín (Hà Nội), tốt nghiệp Trường Thông ngôn, làm thư kí ở các tòa sứ.","Ông tham gia Đông Kinh nghĩa thục, cổ động chữ Quốc ngữ, làm chủ bút Đông Dương tạp chí, Trung Bắc tân văn, dịch nhiều tác phẩm văn học Pháp.","Ông mất năm 1936 ở Lào. Đóng góp của ông cho chữ Quốc ngữ được ghi nhận, còn quan điểm chính trị của ông có nhiều ý kiến khác nhau."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 599","trieu":"nguyenvn"},{"id":"vs59-phamquynh","name":"Phạm Quỳnh","period":"1892–1945","role":"Nhà báo, chủ bút Nam Phong tạp chí","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Gốc Bình Giang (Hải Dương), lớn lên ở Hà Nội; làm chủ bút Nam Phong tạp chí từ năm 1917.","Ông viết nhiều bài khảo cứu, dịch thuật, đề cao Truyện Kiều và chủ trương quân chủ lập hiến; sau làm Thượng thư trong triều Bảo Đại.","Ông bị giết năm 1945. Vai trò của ông vẫn có nhiều đánh giá khác nhau."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 416","trieu":"nguyenvn"},{"id":"vs59-bachthaibuoi","name":"Bạch Thái Bưởi","period":"1874–1932","role":"Nhà tư sản dân tộc","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Quê Thanh Trì (Hà Nội), xuất thân nghèo, làm thư kí cho hãng buôn Pháp rồi tự kinh doanh.","Ông lập công ty vận tải đường sông, cạnh tranh được với các chủ tàu nước ngoài; con tàu Bình Chuẩn do xưởng của ông đóng. Ông còn kinh doanh mỏ, in ấn.","Ông được coi là một trong những nhà tư sản dân tộc tiêu biểu đầu thế kỉ XX."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 38","trieu":"nguyenvn"},{"id":"vs59-trantrongkim","name":"Trần Trọng Kim","period":"1882–1953","role":"Học giả, tác giả Việt Nam sử lược","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Quê Nghi Xuân (Hà Tĩnh), học sư phạm ở Pháp, về làm giáo viên, thanh tra tiểu học.","Ông soạn nhiều sách giáo khoa và các công trình Việt Nam sử lược, Nho giáo, Việt Nam văn phạm (viết chung).","Năm 1945, sau khi Nhật đảo chính Pháp, ông làm Thủ tướng chính phủ Đế quốc Việt Nam trong vài tháng."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 260","trieu":"nguyenvn"},{"id":"vs59-tanda","name":"Tản Đà","period":"1888–1939","role":"Nhà thơ","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Tên thật Nguyễn Khắc Hiếu, quê Khê Thượng, Ba Vì (Hà Nội), xuất thân khoa bảng; lấy bút danh từ núi Tản sông Đà.","Ông làm báo (An Nam tạp chí), viết thơ, văn xuôi, dịch thơ Đường; thơ ông phóng khoáng, lãng mạn.","Ông được coi là gạch nối giữa thơ cũ và Thơ mới."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 181","trieu":"nguyenvn"},{"id":"vs59-ngotatto","name":"Ngô Tất Tố","period":"1894–1954","role":"Nhà văn, nhà báo","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Quê Từ Sơn (Bắc Ninh), xuất thân nhà nho nghèo, sau chuyển sang viết báo, viết văn.","Ông là cây bút xuất sắc của văn học hiện thực trước 1945, tiêu biểu là tiểu thuyết Tắt đèn, phóng sự Việc làng, Tập án cái đình.","Sau Cách mạng tháng Tám, ông tham gia kháng chiến chống Pháp ở Việt Bắc và mất năm 1954."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 524","trieu":"nguyenvn"},{"id":"vs59-nguyensinhsac","name":"Nguyễn Sinh Sắc","period":"1863–1929","role":"Nhà nho yêu nước, thân sinh Chủ tịch Hồ Chí Minh","nhom":"Phong trào yêu nước đầu thế kỉ XX","bio":["Còn tên Nguyễn Sinh Huy, quê Kim Liên, Nam Đàn (Nghệ An), đỗ Phó bảng năm 1901.","Ông làm quan ở Huế, rồi làm Tri huyện Bình Khê (Bình Định), bị cách chức vì xử nhẹ người chống đối.","Ông vào Nam Bộ sống bằng nghề bốc thuốc, dạy học và mất ở Cao Lãnh (Đồng Tháp) năm 1929."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 423","trieu":"nguyenvn"},{"id":"vs59-tranphu","name":"Trần Phú","period":"1904–1931","role":"Tổng Bí thư đầu tiên của Đảng","nhom":"Cách mạng và kháng chiến","bio":["Quê Đức Thọ (Hà Tĩnh), sinh ở Quảng Ngãi, từng làm giáo viên ở Vinh, tham gia Hội Phục Việt, rồi Hội Việt Nam Cách mạng Thanh niên.","Năm 1926 ông sang Quảng Châu dự lớp huấn luyện, sau học ở Liên Xô. Tháng 10/1930, ông soạn Luận cương chính trị và được bầu làm Tổng Bí thư Đảng Cộng sản Đông Dương.","Tháng 4/1931 ông bị bắt ở Sài Gòn, bị tra tấn và mất ngày 6/9/1931 tại nhà thương Chợ Quán, để lại lời dặn: hãy giữ vững chí khí chiến đấu."],"src":"Từ điển nhân vật lịch sử Việt Nam"},{"id":"vs59-lehongphong","name":"Lê Hồng Phong","period":"1902–1942","role":"Tổng Bí thư Đảng (1935–1936)","nhom":"Cách mạng và kháng chiến","bio":["Sinh ở Hưng Nguyên (Nghệ An) trong gia đình nông dân; từng làm thợ ở nhà máy diêm Bến Thủy.","Năm 1924 ông sang Quảng Châu, gia nhập Tâm Tâm xã, rồi Hội Việt Nam Cách mạng Thanh niên; sau học quân sự, chính trị ở Trung Quốc, Liên Xô. Năm 1935 ông dự Đại hội VII Quốc tế Cộng sản và được bầu làm Tổng Bí thư.","Năm 1939 ông bị bắt, bị đày ra Côn Đảo và mất ở đó ngày 6/9/1942."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 392"},{"id":"vs59-hahuytap","name":"Hà Huy Tập","period":"1902–1941","role":"Tổng Bí thư Đảng (1936–1938)","nhom":"Cách mạng và kháng chiến","bio":["Quê Cẩm Xuyên (Hà Tĩnh), xuất thân nhà nho, từng dạy học ở Nha Trang, tham gia Tân Việt.","Ông học ở Liên Xô, về nước khôi phục hệ thống tổ chức Đảng sau khủng bố; năm 1936 được cử làm Tổng Bí thư, chỉ đạo phong trào dân chủ 1936–1939.","Năm 1938 ông bị bắt; ngày 28/8/1941 bị xử bắn ở Hóc Môn."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 447"},{"id":"vs59-nguyenthiminhkhai","name":"Nguyễn Thị Minh Khai","period":"1910–1941","role":"Nữ chiến sĩ cách mạng","nhom":"Cách mạng và kháng chiến","bio":["Sinh ở Vinh (Nghệ An); năm 1927 tham gia Tân Việt, năm 1930 sang Hương Cảng làm việc ở Văn phòng Viễn Đông của Quốc tế Cộng sản.","Năm 1935 bà dự Đại hội VII Quốc tế Cộng sản ở Mát-xcơ-va; về nước làm Bí thư Thành ủy Sài Gòn – Chợ Lớn, chuẩn bị khởi nghĩa Nam Kì.","Bà bị bắt năm 1940 và bị xử bắn ngày 28/8/1941 ở Hóc Môn."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 227"},{"id":"vs59-vovantan","name":"Võ Văn Tần","period":"1894–1941","role":"Lãnh đạo Xứ ủy Nam Kì","nhom":"Cách mạng và kháng chiến","bio":["Sinh ở Đức Hòa (Long An ngày nay) trong gia đình nông dân nghèo có truyền thống yêu nước.","Ông tham gia Thanh niên Cách mạng, rồi Đảng Cộng sản, nhiều năm lãnh đạo phong trào ở Nam Kì, là Bí thư Xứ ủy.","Năm 1940 ông bị bắt; ngày 28/8/1941 bị xử bắn ở Hóc Môn."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 443"},{"id":"vs59-ngogiatu","name":"Ngô Gia Tự","period":"1908–1935","role":"Người lãnh đạo Đông Dương Cộng sản đảng","nhom":"Cách mạng và kháng chiến","bio":["Sinh ngày 3/12/1908 ở Tam Sơn, Từ Sơn (Bắc Ninh). Năm 1925 bị đuổi học vì tham gia bãi khóa đòi tha Phan Bội Châu.","Ông tham gia Thanh niên Cách mạng, đi “vô sản hóa”, là một trong những người lập Đông Dương Cộng sản đảng (1929), sau làm Bí thư Xứ ủy Nam Kì.","Bị bắt năm 1930, đày ra Côn Đảo, ông hi sinh năm 1935 khi vượt biển trốn khỏi nhà tù."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 578"},{"id":"vs59-hoangvanthu","name":"Hoàng Văn Thụ","period":"1906–1944","role":"Ủy viên Thường vụ Trung ương Đảng","nhom":"Cách mạng và kháng chiến","bio":["Người Tày, sinh ở Văn Lãng (Lạng Sơn).","Ông sang Trung Quốc hoạt động, năm 1930 vào Đảng; sau về nước làm Bí thư Xứ ủy Bắc Kì, Ủy viên Thường vụ Trung ương, góp phần xây dựng Mặt trận Việt Minh.","Năm 1943 ông bị bắt và bị xử bắn ngày 24/5/1944 ở Hà Nội."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 498"},{"id":"vs59-phungchikien","name":"Phùng Chí Kiên","period":"1901–1941","role":"Chỉ huy đội du kích Bắc Sơn","nhom":"Cách mạng và kháng chiến","bio":["Sinh ở Diễn Châu (Nghệ An); năm 1926 sang Quảng Châu dự lớp huấn luyện, học Trường quân sự Hoàng Phố.","Ông từng hoạt động ở Trung Quốc, năm 1941 về nước, được cử làm Ủy viên Trung ương, chỉ huy các đội du kích Bắc Sơn.","Tháng 8/1941 ông hi sinh trong một trận chiến đấu ở Bắc Sơn."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 254"},{"id":"vs59-nguyenduccanh","name":"Nguyễn Đức Cảnh","period":"1908–1932","role":"Người lãnh đạo phong trào công nhân","nhom":"Cách mạng và kháng chiến","bio":["Quê Thái Thụy (Thái Bình), giác ngộ cách mạng khi đang học ở Nam Định.","Ông là một trong những người sáng lập Đông Dương Cộng sản đảng, phụ trách công tác công vận, lập Tổng Công hội Bắc Kì.","Bị bắt năm 1930, ông bị xử chém ở Hải Phòng năm 1932."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 44"},{"id":"vs59-phandangluu","name":"Phan Đăng Lưu","period":"1901–1941","role":"Lãnh đạo cách mạng","nhom":"Cách mạng và kháng chiến","bio":["Sinh ngày 2/11/1901 ở Yên Thành (Nghệ An), học Trường Canh nông Tuyên Quang.","Ông tham gia Hội Phục Việt, Tân Việt, rồi Đảng Cộng sản; nhiều lần bị tù. Năm 1939–1940 là Ủy viên Thường vụ Trung ương.","Ông bị bắt năm 1940 và bị xử bắn ở Hóc Môn ngày 28/8/1941."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 314"},{"id":"vs59-tohieu","name":"Tô Hiệu","period":"1912–1944","role":"Người lãnh đạo chi bộ nhà tù Sơn La","nhom":"Cách mạng và kháng chiến","bio":["Sinh ở Văn Giang (Hưng Yên), từng bị đuổi học vì đòi ân xá Phan Bội Châu.","Ông hoạt động ở Hải Phòng, làm Bí thư Thành ủy; bị bắt và đày lên nhà tù Sơn La, nơi ông lập chi bộ đảng trong tù.","Ông mất vì bệnh lao trong nhà tù Sơn La năm 1944; cây đào Tô Hiệu ở đây còn được giữ gìn."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 184"},{"id":"vs59-hotungmau","name":"Hồ Tùng Mậu","period":"1896–1951","role":"Nhà cách mạng","nhom":"Cách mạng và kháng chiến","bio":["Tên thật Hồ Bá Cự, quê Quỳnh Đôi (Nghệ An), xuất thân nhà nho yêu nước.","Ông sang Trung Quốc, lập Tâm Tâm xã (1923), rồi tham gia Hội Việt Nam Cách mạng Thanh niên cùng Nguyễn Ái Quốc.","Sau năm 1945 ông giữ nhiều chức vụ, hi sinh năm 1951 khi máy bay Pháp bắn phá trên đường công tác ở Thanh Hóa."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 327"},{"id":"vs59-kimdong","name":"Kim Đồng","period":"1928–1943","role":"Liệt sĩ thiếu niên","nhom":"Cách mạng và kháng chiến","bio":["Tên thật Nông Văn Dền, người Nùng, quê Nà Mạ, Hà Quảng (Cao Bằng).","Anh tham gia cách mạng từ năm 13 tuổi, là đội trưởng đầu tiên của Đội Nhi đồng cứu quốc, làm liên lạc ở vùng Pác Bó.","Năm 1943, khi đang làm nhiệm vụ, anh bị lính Pháp bắn chết bên bờ suối Lê-nin. Đội Thiếu niên Tiền phong Hồ Chí Minh lấy anh làm tấm gương."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 142"},{"id":"vs59-tranhuylieu","name":"Trần Huy Liệu","period":"1901–1969","role":"Nhà cách mạng, nhà sử học","nhom":"Cách mạng và kháng chiến","bio":["Quê Vụ Bản (Nam Định), viết báo, làm thơ yêu nước từ trẻ; tham gia Việt Nam Quốc dân đảng, nhiều lần bị tù, sau theo Đảng Cộng sản.","Tháng 8/1945, ông thay mặt Chính phủ lâm thời nhận ấn kiếm thoái vị của vua Bảo Đại ở Huế.","Sau đó ông là Viện trưởng Viện Sử học, có công đầu trong việc xây dựng ngành sử học Việt Nam hiện đại."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 291"},{"id":"vs59-tonducthang","name":"Tôn Đức Thắng","period":"1888–1980","role":"Chủ tịch nước (1969–1980)","nhom":"Cách mạng và kháng chiến","bio":["Sinh ngày 20/8/1888 ở Mỹ Hòa Hưng (An Giang), công nhân ở Sài Gòn.","Ông tham gia cuộc binh biến trên chiến hạm Pháp ở Biển Đen ủng hộ nước Nga Xô viết (1919), về nước lập Công hội đỏ, bị tù đày Côn Đảo 17 năm.","Sau năm 1945 ông giữ nhiều chức vụ quan trọng; năm 1969 kế nhiệm Chủ tịch Hồ Chí Minh làm Chủ tịch nước, rồi là Chủ tịch nước Cộng hòa xã hội chủ nghĩa Việt Nam đầu tiên."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 472"},{"id":"vs59-leduan","name":"Lê Duẩn","period":"1907–1986","role":"Bí thư thứ nhất, Tổng Bí thư Đảng (1960–1986)","nhom":"Cách mạng và kháng chiến","bio":["Sinh ngày 7/4/1907 ở Triệu Phong (Quảng Trị), tham gia Tân Việt, Thanh niên Cách mạng, rồi Đảng Cộng sản từ năm 1930; nhiều lần bị tù.","Ông lãnh đạo kháng chiến ở Nam Bộ thời chống Pháp, là tác giả Đề cương cách mạng miền Nam (1956).","Từ năm 1960 ông là Bí thư thứ nhất, sau là Tổng Bí thư, lãnh đạo Đảng trong kháng chiến chống Mĩ và những năm đầu sau thống nhất."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 103"},{"id":"vs59-truongchinh","name":"Trường Chinh","period":"1907–1988","role":"Tổng Bí thư Đảng, Chủ tịch Hội đồng Nhà nước","nhom":"Cách mạng và kháng chiến","bio":["Tên thật Đặng Xuân Khu, sinh ngày 9/2/1907 ở Xuân Trường (Nam Định). Ông tham gia cách mạng từ năm 1925, bị đày ở Sơn La.","Năm 1941 ông được bầu làm Tổng Bí thư; tác giả Đề cương văn hóa Việt Nam (1943) và Kháng chiến nhất định thắng lợi (1947).","Ông giữ chức Chủ tịch Ủy ban Thường vụ Quốc hội, Chủ tịch Hội đồng Nhà nước; năm 1986 lại làm Tổng Bí thư, chuẩn bị đường lối Đổi mới."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 558"},{"id":"vs59-phamhung","name":"Phạm Hùng","period":"1912–1988","role":"Chủ tịch Hội đồng Bộ trưởng","nhom":"Cách mạng và kháng chiến","bio":["Tên thật Phạm Văn Thiện, quê Châu Thành (Vĩnh Long); hoạt động cách mạng từ 1928, bị kết án tử hình rồi đổi ra khổ sai, đày Côn Đảo.","Ông nhiều năm lãnh đạo cách mạng ở miền Nam, là Bí thư Trung ương Cục miền Nam, Chính ủy Chiến dịch Hồ Chí Minh năm 1975.","Năm 1987 ông làm Chủ tịch Hội đồng Bộ trưởng và mất khi đang tại chức năm 1988."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 207"},{"id":"vs59-leductho","name":"Lê Đức Thọ","period":"1911–1990","role":"Cố vấn đặc biệt tại Hội nghị Pa-ri","nhom":"Cách mạng và kháng chiến","bio":["Tên thật Phan Đình Khải, quê Nam Định; hoạt động cách mạng từ năm 1928, nhiều lần bị tù.","Ông lãnh đạo ở Nam Bộ thời chống Pháp, sau là Trưởng ban Tổ chức Trung ương.","Ông là cố vấn đặc biệt của đoàn Việt Nam Dân chủ Cộng hòa tại Hội nghị Pa-ri, đàm phán với Mĩ dẫn tới Hiệp định 27/1/1973."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 490"},{"id":"vs59-nguyenchithanh","name":"Nguyễn Chí Thanh","period":"1914–1967","role":"Đại tướng","nhom":"Cách mạng và kháng chiến","bio":["Sinh ngày 1/1/1914 ở Quảng Điền (Thừa Thiên Huế), gia đình nông dân; hoạt động cách mạng từ 17 tuổi.","Ông là Chủ nhiệm Tổng cục Chính trị Quân đội nhân dân, được phong Đại tướng năm 1959.","Từ năm 1964 ông vào chiến trường miền Nam làm Bí thư Trung ương Cục; mất năm 1967 ở Hà Nội."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 458"},{"id":"vs59-vantiendung","name":"Văn Tiến Dũng","period":"1917–2002","role":"Đại tướng, Tư lệnh Chiến dịch Hồ Chí Minh","nhom":"Cách mạng và kháng chiến","bio":["Sinh ngày 2/5/1917 ở Cổ Nhuế (Hà Nội), tham gia cách mạng từ năm 1936.","Ông làm Tổng Tham mưu trưởng Quân đội nhân dân trong nhiều năm.","Năm 1975 ông là Tư lệnh Chiến dịch Tây Nguyên và Chiến dịch Hồ Chí Minh; sau làm Bộ trưởng Bộ Quốc phòng."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 109"},{"id":"vs59-tranvantra","name":"Trần Văn Trà","period":"1919–1996","role":"Thượng tướng","nhom":"Cách mạng và kháng chiến","bio":["Tên thật Nguyễn Chấn, quê Sơn Tịnh (Quảng Ngãi), tham gia cách mạng từ năm 1936.","Ông chỉ huy lực lượng vũ trang Nam Bộ thời chống Pháp, sau là Tư lệnh Quân giải phóng miền Nam.","Năm 1975 ông là Phó Tư lệnh Chiến dịch Hồ Chí Minh, sau làm Chủ tịch Ủy ban Quân quản Sài Gòn – Gia Định."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 529"},{"id":"vs59-nguyenthidinh","name":"Nguyễn Thị Định","period":"1920–1992","role":"Nữ tướng, Phó Tư lệnh Quân giải phóng","nhom":"Cách mạng và kháng chiến","bio":["Quê Bến Tre, tham gia cách mạng từ nhỏ, vào Đảng năm 1938.","Năm 1960 bà là một trong những người lãnh đạo phong trào Đồng khởi ở Bến Tre; sau làm Phó Tư lệnh Quân giải phóng miền Nam, là nữ thiếu tướng đầu tiên.","Sau năm 1975 bà làm Chủ tịch Hội Liên hiệp Phụ nữ Việt Nam, Phó Chủ tịch nước."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 134"},{"id":"vs59-nguyenhuutho","name":"Nguyễn Hữu Thọ","period":"1910–1996","role":"Chủ tịch Mặt trận Dân tộc giải phóng miền Nam","nhom":"Cách mạng và kháng chiến","bio":["Sinh ở Chợ Lớn, học Luật ở Pháp, làm luật sư ở Sài Gòn.","Ông tham gia phong trào yêu nước, nhiều lần bị bắt; năm 1962 được bầu làm Chủ tịch Ủy ban Trung ương Mặt trận Dân tộc giải phóng miền Nam Việt Nam.","Sau năm 1975 ông làm Phó Chủ tịch nước, Chủ tịch Quốc hội."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 491"},{"id":"vs59-huynhtanphat","name":"Huỳnh Tấn Phát","period":"1913–1989","role":"Chủ tịch Chính phủ Cách mạng lâm thời","nhom":"Cách mạng và kháng chiến","bio":["Sinh ở Bình Đại (Bến Tre), học kiến trúc ở Trường Cao đẳng Mĩ thuật Đông Dương.","Ông tham gia phong trào yêu nước ở Sài Gòn, là một trong những người lãnh đạo Mặt trận Dân tộc giải phóng.","Năm 1969 ông làm Chủ tịch Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam; sau làm Phó Thủ tướng."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 388"},{"id":"vs59-nguyenvanlinh","name":"Nguyễn Văn Linh","period":"1915–1998","role":"Tổng Bí thư Đảng (1986–1991)","nhom":"Cách mạng và kháng chiến","bio":["Tên thật Nguyễn Văn Cúc (Mười Cúc), sinh ngày 1/7/1915 ở Yên Mỹ (Hưng Yên), hoạt động cách mạng từ năm 1929, bị đày Côn Đảo.","Ông nhiều năm lãnh đạo ở miền Nam, sau năm 1975 là Bí thư Thành ủy Thành phố Hồ Chí Minh.","Tại Đại hội VI (12/1986), ông được bầu làm Tổng Bí thư, lãnh đạo những năm đầu của công cuộc Đổi mới."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 293"},{"id":"vs59-nguyencothach","name":"Nguyễn Cơ Thạch","period":"1921–1998","role":"Bộ trưởng Ngoại giao","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Tên thật Phạm Văn Cương, quê Vụ Bản (Nam Định), tham gia phong trào thanh niên từ năm 1937, bị tù ở Sơn La.","Ông là nhà ngoại giao, tham gia đoàn đàm phán tại Hội nghị Pa-ri; làm Bộ trưởng Ngoại giao (1980–1991), Phó Thủ tướng.","Ông góp phần mở ra chính sách đối ngoại thời kì Đổi mới, phá thế bao vây cấm vận."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 449"},{"id":"vs59-tonthattung","name":"Tôn Thất Tùng","period":"1912–1982","role":"Giáo sư, bác sĩ phẫu thuật","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Sinh ở Huế, tốt nghiệp xuất sắc Đại học Y khoa Hà Nội năm 1939, làm bác sĩ nội trú ở bệnh viện Phủ Doãn (nay là Bệnh viện Việt Đức).","Ông nổi tiếng thế giới với phương pháp cắt gan khô (“phương pháp Tôn Thất Tùng”).","Ông tham gia kháng chiến chống Pháp, sau là Giám đốc Bệnh viện Việt Đức, Thứ trưởng Bộ Y tế, đào tạo nhiều thế hệ bác sĩ ngoại khoa."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 569"},{"id":"vs59-trandainghia","name":"Trần Đại Nghĩa","period":"1913–1997","role":"Nhà khoa học quân sự","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Tên thật Phạm Quang Lễ, quê Vĩnh Long, học kĩ sư ở Pháp và làm việc trong ngành chế tạo vũ khí.","Năm 1946, ông theo Chủ tịch Hồ Chí Minh về nước, được Người đặt tên là Trần Đại Nghĩa, phụ trách Cục Quân giới.","Ông chỉ đạo chế tạo súng ba-dô-ca, súng không giật SKZ phục vụ kháng chiến; là Anh hùng Lao động đầu tiên (1952)."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 349"},{"id":"vs59-taquangbuu","name":"Tạ Quang Bửu","period":"1910–1986","role":"Nhà toán học, nhà giáo dục","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Sinh ngày 23/7/1910 ở Nam Đàn (Nghệ An), du học ở Pháp, Anh.","Ông là Thứ trưởng Bộ Quốc phòng, thành viên đoàn đại biểu tại Hội nghị Giơ-ne-vơ năm 1954, người kí văn bản đình chiến về quân sự.","Sau đó ông làm Bộ trưởng Bộ Đại học và Trung học chuyên nghiệp, có công lớn trong xây dựng nền giáo dục đại học."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 40"},{"id":"vs59-phamngocthach","name":"Phạm Ngọc Thạch","period":"1909–1968","role":"Bác sĩ, Bộ trưởng Bộ Y tế","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Sinh ngày 7/5/1909 ở Sài Gòn, đỗ bác sĩ y khoa ở Hà Nội; tham gia phong trào Thanh niên Tiền phong năm 1945.","Ông làm Bộ trưởng Bộ Y tế trong nhiều năm, đi đầu trong phòng chống bệnh lao, xây dựng ngành y tế dự phòng.","Năm 1968, khi vào chiến trường miền Nam nghiên cứu bệnh sốt rét, ông mắc bệnh và hi sinh."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 450"},{"id":"vs59-dangvanngu","name":"Đặng Văn Ngữ","period":"1910–1967","role":"Giáo sư, nhà kí sinh trùng học","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Sinh ở Huế, học Đại học Y khoa Hà Nội, sau nghiên cứu ở Nhật Bản.","Năm 1949 ông về nước tham gia kháng chiến, sản xuất thuốc kháng sinh nước lọc Pê-ni-xi-lin phục vụ thương binh.","Ông hi sinh năm 1967 ở chiến trường Trị – Thiên khi đang nghiên cứu phòng chống sốt rét cho bộ đội."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 358"},{"id":"vs59-tovinhdien","name":"Tô Vĩnh Diện","period":"1924–1954","role":"Anh hùng lấy thân chèn pháo","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Sinh ở Nông Cống (Thanh Hóa) trong gia đình nông dân nghèo; nhập ngũ sau Cách mạng tháng Tám.","Đầu năm 1954, trong chiến dịch Điện Biên Phủ, khi kéo pháo ra khỏi trận địa ở dốc núi, dây kéo bị đứt, anh lao vào lấy thân mình chèn pháo để khẩu pháo không lao xuống vực.","Anh hi sinh và được truy tặng danh hiệu Anh hùng Lực lượng vũ trang nhân dân."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 95"},{"id":"vs59-bevandan","name":"Bế Văn Đàn","period":"1931–1953","role":"Anh hùng lấy thân làm giá súng","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Người Tày, quê Phục Hòa (Cao Bằng), mồ côi cha sớm.","Tháng 12/1953, trong trận Mường Pồn (Điện Biên), khi khẩu trung liên không có chỗ đặt, anh lấy vai mình làm giá súng cho đồng đội bắn, giữ vững trận địa.","Anh hi sinh và được truy tặng danh hiệu Anh hùng Lực lượng vũ trang nhân dân."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 121"},{"id":"vs59-phandinhgiot","name":"Phan Đình Giót","period":"1920–1954","role":"Anh hùng lấy thân lấp lỗ châu mai","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Quê Cẩm Xuyên (Hà Tĩnh), nhà nghèo, đi ở từ năm 13 tuổi; nhập ngũ sau Cách mạng tháng Tám.","Ngày 13/3/1954, trong trận đánh đồi Him Lam mở màn chiến dịch Điện Biên Phủ, anh lao lên lấy thân mình lấp lỗ châu mai đang bắn mạnh, mở đường cho đồng đội xung phong.","Anh được truy tặng danh hiệu Anh hùng Lực lượng vũ trang nhân dân."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 157"},{"id":"vs59-dinhnup","name":"Đinh Núp","period":"1914–1999","role":"Anh hùng dân tộc Ba Na","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Người Ba Na, lớn lên ở làng Stơr (Kbang, Gia Lai); tham gia cách mạng từ năm 1943.","Thời chống Pháp, ông vận động dân làng làm vũ khí thô sơ, chông, bẫy đánh giặc, biến Stơr thành làng kháng chiến.","Năm 1955 ông được tuyên dương Anh hùng Lực lượng vũ trang nhân dân; câu chuyện của ông được kể lại trong tiểu thuyết Đất nước đứng lên."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 375"},{"id":"vs59-macthibuoi","name":"Mạc Thị Bưởi","period":"1927–1951","role":"Nữ anh hùng du kích","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Quê Nam Sách (Hải Dương), tham gia chiến đấu chống Pháp ngay khi quân Pháp đánh chiếm quê hương.","Chị là cán bộ phụ nữ, du kích hoạt động trong vùng tạm chiếm, nhiều lần thoát vòng vây địch.","Năm 1951, chị bị bắt, bị tra tấn dã man nhưng không khai và hi sinh; được truy tặng danh hiệu Anh hùng Lực lượng vũ trang nhân dân."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 39"},{"id":"vs59-vancao","name":"Văn Cao","period":"1923–1995","role":"Nhạc sĩ, tác giả Quốc ca","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Tên thật Nguyễn Văn Cao, quê gốc Nam Định, lớn lên ở Hải Phòng; hoạt động trong cả âm nhạc, thơ và hội họa.","Năm 1944, ông sáng tác bài Tiến quân ca, được Quốc hội chọn làm Quốc ca nước Việt Nam.","Ông còn có nhiều ca khúc nổi tiếng như Thiên Thai, Trường ca sông Lô, Mùa xuân đầu tiên."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 589"},{"id":"vs59-tohuu","name":"Tố Hữu","period":"1920–2002","role":"Nhà thơ cách mạng","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Tên thật Nguyễn Kim Thành, sinh ngày 4/10/1920 ở Thừa Thiên Huế; hoạt động cách mạng từ trẻ, bị tù nhiều nơi.","Thơ ông gắn với từng chặng đường cách mạng qua các tập Từ ấy, Việt Bắc, Gió lộng, Ra trận…","Ông giữ nhiều chức vụ lãnh đạo về văn hóa, tư tưởng và Phó Chủ tịch Hội đồng Bộ trưởng."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 219"},{"id":"vs59-daoduyanh","name":"Đào Duy Anh","period":"1904–1988","role":"Nhà sử học, từ điển học","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Sinh ở Thanh Hóa, học ở Quốc học Huế; tham gia Hội Phục Việt, Tân Việt.","Ông biên soạn Hán – Việt từ điển, Pháp – Việt từ điển và nhiều công trình nghiên cứu lịch sử, văn hóa như Việt Nam văn hóa sử cương, Đất nước Việt Nam qua các đời.","Ông là một trong những người đặt nền móng cho khoa học lịch sử Việt Nam hiện đại."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 13"},{"id":"vs59-hoangxuanhan","name":"Hoàng Xuân Hãn","period":"1908–1996","role":"Nhà sử học, nhà giáo","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Quê Đức Thọ (Hà Tĩnh), du học ở Pháp, tốt nghiệp Trường Bách khoa và thạc sĩ toán.","Ông soạn Danh từ khoa học (1942) đặt nền cho thuật ngữ khoa học tiếng Việt; năm 1945 làm Bộ trưởng Giáo dục chính phủ Trần Trọng Kim, cho dạy bằng tiếng Việt ở bậc trung học.","Ông nghiên cứu sâu về lịch sử với các công trình Lý Thường Kiệt, La Sơn phu tử…"],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 166"},{"id":"vs59-nguyenvanhuyen","name":"Nguyễn Văn Huyên","period":"1908–1975","role":"Nhà dân tộc học, Bộ trưởng Giáo dục","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Quê Đan Phượng (Hà Nội), tiến sĩ văn khoa ở Pháp, nghiên cứu văn hóa dân gian, dân tộc học Việt Nam.","Từ năm 1946 đến 1975, ông làm Bộ trưởng Bộ Giáo dục, tổ chức phong trào Bình dân học vụ và xây dựng nền giáo dục mới.","Ông là tác giả nhiều công trình về văn minh Việt Nam."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 209"},{"id":"vs59-luuhuuphuoc","name":"Lưu Hữu Phước","period":"1921–1989","role":"Nhạc sĩ","nhom":"Khoa học – văn hóa – anh hùng thế kỉ XX","bio":["Sinh ngày 12/9/1921 ở Sóc Trăng, hoạt động trong phong trào sinh viên yêu nước.","Ông sáng tác nhiều bài hát cổ vũ thanh niên như Lên đàng, Tiếng gọi sinh viên, Bạch Đằng giang, và bài Giải phóng miền Nam.","Ông từng làm Bộ trưởng Bộ Thông tin – Văn hóa của Chính phủ Cách mạng lâm thời."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 401"},{"id":"vs59-tuetinh","name":"Tuệ Tĩnh","period":"thế kỉ XIV","role":"Danh y thời Trần","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Tên thật Nguyễn Bá Tĩnh, quê Cẩm Giàng (Hải Dương), mồ côi từ nhỏ, được nuôi dạy ở chùa.","Ông chủ trương “Nam dược trị Nam nhân”, dùng thuốc nam chữa bệnh cho người Việt, biên soạn Nam dược thần hiệu và Hồng Nghĩa giác tư y thư.","Ông được coi là ông tổ của ngành thuốc nam."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 568","trieu":"tran"},{"id":"vs59-huyenquang","name":"Huyền Quang","period":"1254–1334","role":"Tổ thứ ba Thiền phái Trúc Lâm","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Họ Lý, tên Đạo Tái, quê Gia Bình (Bắc Ninh), đỗ Trạng nguyên rồi xuất gia.","Ông học đạo với Trần Nhân Tông và Pháp Loa, sau làm tổ thứ ba của dòng Thiền Trúc Lâm Yên Tử.","Ông còn là nhà thơ nổi tiếng với những bài thơ thiền giàu chất trữ tình."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 210","trieu":"tran"},{"id":"vs59-phaploa","name":"Pháp Loa","period":"1284–1330","role":"Tổ thứ hai Thiền phái Trúc Lâm","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Họ Đồng, tên Kiên Cương, quê Chí Linh (Hải Dương).","Ông được Trần Nhân Tông truyền y bát làm tổ thứ hai dòng Thiền Trúc Lâm, có công tổ chức giáo hội, in kinh, dựng chùa.","Ông để lại nhiều tác phẩm về Phật học."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 386","trieu":"tran"},{"id":"vs59-tuetrung","name":"Tuệ Trung Thượng sĩ","period":"1230–1291","role":"Nhà Phật học thời Trần","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Tên thật Trần Tung, tước Hưng Ninh vương, con Trần Liễu, anh của Trần Quốc Tuấn.","Ông có công trong kháng chiến chống Nguyên, sau lui về sống ẩn dật, nghiên cứu thiền học.","Ông là người thầy hướng dẫn Trần Nhân Tông về thiền, ảnh hưởng lớn tới Thiền phái Trúc Lâm."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 568","trieu":"tran"},{"id":"vs59-truonghansieu","name":"Trương Hán Siêu","period":"?–1355","role":"Nhà văn, nhà chính trị thời Trần","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Tự Thăng Phủ, quê Yên Khánh (Ninh Bình), từng là môn khách của Trần Hưng Đạo.","Ông giữ chức Hành khiển, cùng Nguyễn Trung Ngạn soạn bộ Hoàng triều đại điển và Hình thư.","Ông là tác giả Bạch Đằng giang phú, áng văn nổi tiếng ca ngợi chiến thắng trên sông Bạch Đằng."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 428","trieu":"tran"},{"id":"vs59-nguyentrungngan","name":"Nguyễn Trung Ngạn","period":"1289–1370","role":"Danh thần nhà Trần","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Tự Giới Hiên, quê Ân Thi (Hưng Yên), đỗ Hoàng giáp khi mới 16 tuổi.","Ông đi sứ nhà Nguyên, làm quan đến Đại hành khiển, cùng Trương Hán Siêu biên soạn luật pháp thời Trần.","Ông nổi tiếng thanh liêm và là nhà thơ của thời Trần."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 343","trieu":"tran"},{"id":"vs59-huyentran","name":"Huyền Trân công chúa","period":"thế kỉ XIII – XIV","role":"Công chúa nhà Trần","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Con gái vua Trần Nhân Tông. Năm 1306, bà được gả cho vua Chăm-pa là Chế Mân; Chế Mân dâng hai châu Ô, Lý làm sính lễ.","Năm 1307 Chế Mân mất, nhà Trần sai Trần Khắc Chung đưa bà về nước.","Hai châu Ô, Lý được đổi thành châu Thuận, châu Hóa."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 211","trieu":"tran"},{"id":"vs59-chebongnga","name":"Chế Bồng Nga","period":"?–1390","role":"Vua Chăm-pa","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Vua Chăm-pa nửa sau thế kỉ XIV, có tài cầm quân, nhiều lần đem quân đánh Đại Việt.","Quân Chăm-pa của ông từng vào Thăng Long các năm 1371, 1377, 1378, 1383; vua Trần Duệ Tông tử trận khi đánh Chăm-pa năm 1377.","Năm 1390, ông bị quân Trần bắn chết trên sông Hải Triều."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 341","trieu":"tran"},{"id":"vs59-trankhacchung","name":"Trần Khắc Chung","period":"?–1330","role":"Danh thần đời Trần","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Vốn họ Đỗ, quê Hải Dương. Năm 1285 ông được cử sang doanh trại quân Nguyên thương thuyết, ứng đối khéo léo.","Năm 1307, ông được giao đưa công chúa Huyền Trân từ Chăm-pa về nước.","Ông làm quan đến chức Hành khiển."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 79","trieu":"tran"},{"id":"vs59-nguyenhien","name":"Nguyễn Hiền","period":"1235–1255","role":"Trạng nguyên trẻ nhất","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Quê Mỹ Lộc (Nam Định), nổi tiếng thông minh từ nhỏ.","Năm 1247, ông đỗ Trạng nguyên khi mới 12 tuổi, là trạng nguyên trẻ nhất trong lịch sử khoa cử Việt Nam.","Ông làm quan đến Thượng thư bộ Công nhưng mất sớm."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 174","trieu":"tran"},{"id":"vs59-lydaothanh","name":"Lý Đạo Thành","period":"?–1081","role":"Thái sư thời Lý","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Người trong họ Lý, quê Cổ Pháp (Bắc Ninh), làm Thái sư thời Lý Thánh Tông.","Khi Lý Nhân Tông còn nhỏ lên ngôi, ông được giao phò chính; tuy bị giáng chức một thời gian nhưng sau được gọi về, cùng Ỷ Lan và Lý Thường Kiệt điều hành việc nước.","Ông nổi tiếng là người ngay thẳng, lo việc dân."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 463","trieu":"ly"},{"id":"vs59-tudaohanh","name":"Từ Đạo Hạnh","period":"?–1116","role":"Thiền sư thời Lý","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Tên Lộ, quê Láng (Hà Nội), con quan Đô sát Từ Vinh.","Ông xuất gia, tu ở chùa Thầy (núi Sài Sơn, Quốc Oai), giỏi y thuật và nhiều truyền thuyết gắn với ông.","Dân gian thờ ông ở chùa Láng, chùa Thầy; lễ hội chùa Thầy gắn với nghệ thuật múa rối nước."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 169","trieu":"ly"},{"id":"vs59-minhkhong","name":"Minh Không","period":"1066–1141","role":"Thiền sư thời Lý","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Tên Nguyễn Chí Thành, quê Gia Viễn (Ninh Bình), học đạo với Từ Đạo Hạnh.","Theo truyền tụng, ông chữa khỏi bệnh lạ cho vua Lý Thần Tông, được phong Quốc sư.","Ông được tôn là ông tổ nghề đúc đồng."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 329","trieu":"ly"},{"id":"vs59-dinhliet","name":"Đinh Liệt","period":"?–1471","role":"Danh tướng Lam Sơn, đại thần Lê sơ","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Em Đinh Lễ, cháu Lê Lợi, quê Thanh Hóa, tham gia khởi nghĩa Lam Sơn từ đầu.","Ông lập công trong nhiều trận đánh quân Minh; năm 1460 cùng Nguyễn Xí phế Lê Nghi Dân, đưa Lê Thánh Tông lên ngôi.","Ông làm quan đến Thái sư."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 289","trieu":"leso"},{"id":"vs59-nguyenchich","name":"Nguyễn Chích","period":"1382–1449","role":"Danh tướng khởi nghĩa Lam Sơn","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Quê Đông Sơn (Thanh Hóa), từng tự khởi binh chống Minh ở vùng Thanh – Nghệ trước khi theo Lê Lợi.","Năm 1424 ông hiến kế đưa nghĩa quân vào Nghệ An, mở ra bước ngoặt cho cuộc khởi nghĩa.","Sau chiến thắng, ông trấn giữ phía nam, làm đến Thái bảo."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 70","trieu":"leso"},{"id":"vs59-nguyenthilo","name":"Nguyễn Thị Lộ","period":"?–1442","role":"Vợ Nguyễn Trãi","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Bà giỏi văn chương, được vua Lê Thái Tông cho vào cung giữ chức Lễ nghi học sĩ.","Năm 1442, vua Thái Tông đột ngột mất ở vườn Lệ Chi; bà và Nguyễn Trãi bị vu tội giết vua, bị xử tru di ba họ.","Năm 1464, vua Lê Thánh Tông minh oan cho Nguyễn Trãi."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 302","trieu":"leso"},{"id":"vs59-trinhkha","name":"Trịnh Khả","period":"1391–1451","role":"Danh tướng khởi nghĩa Lam Sơn","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Quê Vĩnh Lộc (Thanh Hóa), tham gia khởi nghĩa Lam Sơn và lập nhiều chiến công.","Sau chiến thắng, ông làm quan đến Tư không, Thái úy.","Năm 1451 ông bị giết oan; về sau được minh oan."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 226","trieu":"leso"},{"id":"vs59-thannhantrung","name":"Thân Nhân Trung","period":"1419–1499","role":"Nhà thơ, nhà giáo dục","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Tự Hậu Phủ, quê Yên Dũng (Bắc Giang), đỗ Tiến sĩ năm 1469, làm Tế tửu Quốc Tử Giám.","Ông là Phó nguyên súy Hội Tao đàn của vua Lê Thánh Tông.","Ông soạn bài kí trên tấm bia tiến sĩ khoa Nhâm Tuất (1442) dựng ở Văn Miếu năm 1484, có câu “Hiền tài là nguyên khí của quốc gia”."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 550","trieu":"leso"},{"id":"vs59-vuquynh","name":"Vũ Quỳnh","period":"1452–1516","role":"Sử gia thời Lê sơ","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Quê Bình Giang (Hải Dương), đỗ Tiến sĩ năm 1478, làm quan đến Thượng thư.","Ông biên soạn Đại Việt thông giám thông khảo, bộ sử chép từ thời Hồng Bàng đến năm 1427.","Ông còn hiệu đính Lĩnh Nam chích quái."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 417","trieu":"leso"},{"id":"vs59-giangvanminh","name":"Giang Văn Minh","period":"1573–1638","role":"Sứ thần nhà Lê","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Quê Đường Lâm (Sơn Tây), đỗ Thám hoa năm 1628.","Năm 1637 ông đi sứ nhà Minh, đối đáp khảng khái để giữ thể diện quốc gia, nhắc lại các chiến thắng Bạch Đằng.","Theo sử cũ, vua Minh tức giận cho giết ông năm 1638. Ông được truy tặng “Sứ thần vạn cổ anh hùng”."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 331","trieu":"letrung"},{"id":"vs59-duongvannga","name":"Dương Vân Nga","period":"?–1000","role":"Hoàng hậu thời Đinh và Tiền Lê","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Con gái một nha tướng của Dương Đình Nghệ, vợ Đinh Tiên Hoàng, mẹ Đinh Toàn.","Năm 979 Đinh Tiên Hoàng bị giết, Đinh Toàn còn nhỏ; năm 980 trước nguy cơ quân Tống xâm lược, bà trao áo long cổn cho Lê Hoàn lên ngôi.","Sau đó bà là hoàng hậu của Lê Đại Hành."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 342","trieu":"dinh"},{"id":"vs59-caobien","name":"Cao Biền","period":"thế kỉ IX","role":"Tướng nhà Đường","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Người U Châu (Trung Quốc), tướng nhà Đường.","Năm 865–866, ông được cử sang đánh đuổi quân Nam Chiếu ra khỏi Giao Châu, sau làm Tiết độ sứ Tĩnh Hải quân.","Ông cho đắp lại thành Đại La; dân gian có nhiều truyền thuyết về ông."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 612"},{"id":"vs59-mavien","name":"Mã Viện","period":"?–49","role":"Tướng nhà Đông Hán","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Tướng nhà Đông Hán, từng đàn áp nhiều cuộc nổi dậy ở phía nam Trung Quốc.","Năm 42–43, ông được cử đem quân đánh cuộc khởi nghĩa Hai Bà Trưng.","Sau đó ông tổ chức lại bộ máy cai trị ở Giao Chỉ, đẩy mạnh chính sách đồng hóa."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 633"},{"id":"vs59-todinh","name":"Tô Định","period":"thế kỉ I","role":"Thái thú Giao Chỉ","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Người Hán, làm Thái thú Giao Chỉ từ năm 34, nổi tiếng tham lam, tàn bạo.","Ông giết Thi Sách, chồng bà Trưng Trắc, khiến căm phẫn dâng cao.","Năm 40, khởi nghĩa Hai Bà Trưng bùng nổ, Tô Định phải trốn chạy về nước."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 616"},{"id":"vs59-samnghidong","name":"Sầm Nghi Đống","period":"?–1789","role":"Tướng nhà Thanh","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Tri phủ Điền Châu (Quảng Tây), năm 1788 theo Tôn Sĩ Nghị đem quân sang Đại Việt.","Ông đóng quân ở đồn Khương Thượng (Đống Đa, Hà Nội).","Mùng 5 Tết Kỉ Dậu (1789), quân Tây Sơn đánh tan đồn này, ông thắt cổ tự tử."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 617"},{"id":"vs59-lieuthang","name":"Liễu Thăng","period":"?–1427","role":"Tướng nhà Minh","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Tướng nhà Minh, từng theo Trương Phụ xâm lược Đại Việt, đuổi bắt Hồ Quý Ly.","Năm 1427, ông chỉ huy đạo viện binh lớn sang cứu Vương Thông.","Ông bị nghĩa quân Lam Sơn phục kích và chém tại ải Chi Lăng."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 629"},{"id":"vs59-toado","name":"Toa Đô","period":"?–1285","role":"Tướng nhà Nguyên","nhom":"Các triều Lý – Trần – Lê và nhân vật nước ngoài","bio":["Tướng nhà Nguyên, năm 1282 được cử đánh Chăm-pa.","Năm 1285, ông từ Chăm-pa đánh ra phía bắc, phối hợp với đạo quân Thoát Hoan đánh Đại Việt.","Ông bị quân Trần chém trong trận Tây Kết năm 1285."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 617"},{"id":"vs59-thanhgiong","name":"Thánh Gióng (Phù Đồng Thiên Vương)","period":"thời Hùng Vương (truyền thuyết)","role":"Anh hùng truyền thuyết","nhom":"Truyền thuyết","bio":["Theo truyền thuyết, cậu bé làng Gióng (Gia Lâm, Hà Nội) lên ba tuổi chưa biết nói, khi giặc Ân sang xâm lược thì cất tiếng xin đi đánh giặc.","Cậu vươn vai thành tráng sĩ, cưỡi ngựa sắt, cầm roi sắt đánh tan giặc; roi gãy thì nhổ tre đánh tiếp, rồi bay về trời ở núi Sóc Sơn.","Đây là truyền thuyết, không phải sử liệu. Hội Gióng ở đền Phù Đổng và đền Sóc được UNESCO ghi danh là di sản văn hóa phi vật thể."],"src":"Từ điển nhân vật lịch sử Việt Nam","trieu":"hongbang"},{"id":"phanboichau","name":"Phan Bội Châu","period":"1867–1940","role":"Chí sĩ yêu nước","bo_sung":true,"bio":["Hiệu Sào Nam, quê Nam Đàn (Nghệ An), đỗ Giải nguyên năm 1900.","Năm 1904 ông lập Duy Tân hội, năm 1905 sang Nhật khởi xướng phong trào Đông Du đưa thanh niên sang học. Năm 1912 lập Việt Nam Quang phục hội ở Trung Quốc, chủ trương dùng bạo động giành độc lập.","Năm 1925 ông bị Pháp bắt ở Thượng Hải, đưa về nước xử án; phong trào đòi ân xá khắp cả nước buộc Pháp phải tha, nhưng giam lỏng ở Huế đến khi mất năm 1940 (ông già Bến Ngự)."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 64"},{"id":"huynhthuckhang","name":"Huỳnh Thúc Kháng","period":"1876–1947","role":"Chí sĩ, Quyền Chủ tịch nước (1946)","bo_sung":true,"bio":["Quê Tiên Phước (Quảng Nam), đỗ Hội nguyên năm 1904, cùng Phan Châu Trinh, Trần Quý Cáp cổ động phong trào Duy tân.","Năm 1908 ông bị bắt vì phong trào chống thuế, bị đày Côn Đảo 13 năm. Ra tù, ông làm Viện trưởng Viện Dân biểu Trung Kì, sáng lập báo Tiếng Dân.","Năm 1946 ông làm Bộ trưởng Bộ Nội vụ và Quyền Chủ tịch nước khi Chủ tịch Hồ Chí Minh sang Pháp; mất năm 1947 ở Quảng Ngãi."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 233"},{"id":"vonguyengiap","name":"Võ Nguyên Giáp","period":"1911–2013","role":"Đại tướng, Tổng Tư lệnh Quân đội nhân dân Việt Nam","bo_sung":true,"bio":["Quê Lệ Thủy (Quảng Bình), học Quốc học Huế, cử nhân Luật, từng dạy sử ở trường Thăng Long (Hà Nội).","Ngày 22/12/1944 ông chỉ huy Đội Việt Nam Tuyên truyền Giải phóng quân. Năm 1948 được phong Đại tướng; ông là Tổng chỉ huy chiến dịch Điện Biên Phủ (1954).","Trong kháng chiến chống Mĩ, ông là Bộ trưởng Quốc phòng, Phó Thủ tướng, cùng Bộ Chính trị chỉ đạo các chiến dịch lớn đến năm 1975."],"src":"Từ điển nhân vật lịch sử Việt Nam"},{"id":"phamvandong","name":"Phạm Văn Đồng","period":"1906–2000","role":"Thủ tướng Chính phủ (1955–1987)","bo_sung":true,"bio":["Quê Mộ Đức (Quảng Ngãi), tham gia Hội Việt Nam Cách mạng Thanh niên, bị tù Côn Đảo từ 1929 đến 1936.","Năm 1954 ông là Trưởng đoàn Việt Nam Dân chủ Cộng hòa tại Hội nghị Giơ-ne-vơ.","Ông làm Thủ tướng hơn 30 năm, qua các thời kì kháng chiến chống Mĩ, thống nhất và những năm đầu Đổi mới."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 142"},{"id":"hoangvanthai","name":"Hoàng Văn Thái","period":"1915–1986","role":"Đại tướng, Tổng Tham mưu trưởng đầu tiên","bo_sung":true,"bio":["Tên thật Hoàng Văn Xiêm, quê Tiền Hải (Thái Bình), hoạt động cách mạng từ những năm 1930.","Năm 1945 ông là Tổng Tham mưu trưởng đầu tiên của Quân đội nhân dân Việt Nam, tham mưu cho các chiến dịch lớn như Biên giới, Điện Biên Phủ.","Trong kháng chiến chống Mĩ ông là Tư lệnh Quân giải phóng miền Nam; được phong Đại tướng năm 1980."],"src":"Từ điển nhân vật lịch sử Việt Nam, tr. PDF 451"}],"su_kien":[{"id":"vs59-sk-722","nam":722,"bieu_tuong":"✦","ten":"Khởi nghĩa Mai Thúc Loan","doan":["Năm 722, Mai Thúc Loan ở Hoan Châu (Nghệ An – Hà Tĩnh ngày nay) dấy binh chống ách cai trị và thuế nặng của nhà Đường, liên kết được nhiều châu quận và cả các nước lân cận.","Ông xưng đế, sử gọi là Mai Hắc Đế, đóng căn cứ ở Vạn An. Nhà Đường phải huy động đại quân mới dập tắt được cuộc khởi nghĩa."],"lien":["maithucloan"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 103"},{"id":"vs59-sk-791","nam":791,"bieu_tuong":"✦","ten":"Phùng Hưng làm chủ phủ thành Tống Bình","doan":["Phùng Hưng, một hào trưởng ở Đường Lâm, cùng em là Phùng Hãi nổi dậy chống viên đô hộ tàn bạo, đánh chiếm phủ thành Tống Bình và tự quản lí đất nước trong một thời gian.","Sau khi ông mất, nhân dân tôn ông là Bố Cái Đại Vương. Con ông là Phùng An giữ quyền được ít lâu rồi nhà Đường lấy lại Giao Châu."],"lien":["phunghung"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 103"},{"id":"vs59-sk-863","nam":863,"bieu_tuong":"⚔","ten":"Nam Chiếu đánh chiếm Giao Châu","doan":["Quân Nam Chiếu từ vùng Vân Nam nhiều lần tràn xuống, đến năm 863 chiếm được phủ thành Giao Châu, gây cảnh tàn phá nặng nề.","Năm 865–866, nhà Đường cử Cao Biền sang đánh đuổi quân Nam Chiếu, sau đó đắp lại thành Đại La và lập Tĩnh Hải quân."],"lien":["vs59-caobien"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 101"},{"id":"vs59-sk-968","nam":968,"bieu_tuong":"⚑","ten":"Đinh Tiên Hoàng lên ngôi, quốc hiệu Đại Cồ Việt","doan":["Sau khi dẹp xong loạn 12 sứ quân, năm 968 Đinh Bộ Lĩnh lên ngôi hoàng đế, đặt tên nước là Đại Cồ Việt, đóng đô ở Hoa Lư.","Triều Đinh đặt ra triều nghi, phẩm hàm quan văn võ, chia quân đội thành các đạo, mở đầu việc xây dựng nhà nước quân chủ tập quyền."],"lien":["dinhbolinh","vs56-dinhlien","nguyenbac"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 115"},{"id":"vs59-sk-1010","nam":1010,"bieu_tuong":"◈","ten":"Chiếu dời đô ra Thăng Long","doan":["Năm 1010, Lý Thái Tổ ban chiếu dời đô từ Hoa Lư ra thành Đại La và đổi tên là Thăng Long, nơi có địa thế trung tâm, đất rộng và bằng phẳng.","Việc dời đô cho thấy tầm nhìn xây dựng một quốc gia ổn định, lâu dài; Thăng Long từ đó là kinh đô của nhiều triều đại."],"lien":["lythaito","vanhanh"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 133"},{"id":"vs59-sk-1044","nam":1044,"bieu_tuong":"⚔","ten":"Lý Thái Tông đánh Chiêm Thành","doan":["Do Chiêm Thành thường quấy nhiễu biên giới phía nam, năm 1044 vua Lý Thái Tông thân chinh đánh Chiêm, phá kinh thành Phật Thệ.","Chiến thắng làm yên biên cương phía nam trong một thời gian và nâng cao uy thế của nhà Lý."],"lien":["vs56-lythaitong"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 138"},{"id":"vs59-sk-1054","nam":1054,"bieu_tuong":"⚑","ten":"Quốc hiệu Đại Việt","doan":["Năm 1054, vua Lý Thánh Tông lên ngôi và đổi quốc hiệu từ Đại Cồ Việt thành Đại Việt.","Quốc hiệu Đại Việt được dùng suốt nhiều thế kỉ sau đó, gắn với các triều Lý, Trần, Lê."],"lien":["vs56-lythanhtong"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 138"},{"id":"vs59-sk-1069","nam":1069,"bieu_tuong":"⚔","ten":"Lý Thánh Tông đánh Chiêm, thu ba châu","doan":["Năm 1069, Lý Thánh Tông cùng Lý Thường Kiệt đem quân đánh Chiêm Thành, bắt được vua Chiêm là Chế Củ.","Để được tha về, Chế Củ dâng ba châu Địa Lý, Ma Linh, Bố Chính (vùng Quảng Bình, bắc Quảng Trị ngày nay) cho Đại Việt."],"lien":["vs56-lythanhtong","lythuongkiet"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 151"},{"id":"vs59-sk-1070","nam":1070,"bieu_tuong":"◈","ten":"Dựng Văn Miếu, mở khoa thi đầu tiên","doan":["Năm 1070, nhà Lý dựng Văn Miếu ở Thăng Long thờ Khổng Tử. Năm 1075 mở khoa thi Minh kinh bác học đầu tiên; năm 1076 lập Quốc Tử Giám.","Đây là bước khởi đầu của nền giáo dục, khoa cử Nho học, bên cạnh vai trò lớn của Phật giáo thời Lý."],"lien":["vs56-lythanhtong","lynhantong","levanthinh"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 159"},{"id":"vs59-sk-1282","nam":1282,"bieu_tuong":"⚑","ten":"Hội nghị Bình Than","doan":["Trước nguy cơ quân Nguyên mượn đường đánh Chiêm Thành để đánh Đại Việt, cuối năm 1282 triều Trần họp các vương hầu, quan lại ở Bình Than (Hải Dương) bàn kế giữ nước.","Hội nghị cử Trần Quốc Tuấn làm Quốc công tiết chế chỉ huy quân đội; tại đây có chuyện Trần Quốc Toản vì nhỏ tuổi không được dự họp, về tự lập đội quân riêng (theo truyền tụng)."],"lien":["nhantong","hungdao","vs56-tranquoctoan"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 182"},{"id":"vs59-sk-1284","nam":1284,"bieu_tuong":"⚑","ten":"Hội nghị Diên Hồng","doan":["Đầu năm 1285 (cuối năm Giáp Thân 1284 âm lịch), Thượng hoàng Trần Thánh Tông mời các bô lão trong nước về điện Diên Hồng hỏi ý nên hòa hay nên đánh.","Các bô lão đồng thanh xin đánh. Hội nghị thể hiện ý chí đồng lòng của toàn dân trước cuộc xâm lược lần thứ hai của quân Nguyên."],"lien":["vs56-tranthanhtong","nhantong","vs59-toado"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 183"},{"id":"vs59-sk-1306","nam":1306,"bieu_tuong":"⚑","ten":"Huyền Trân công chúa và châu Ô, châu Lý","doan":["Năm 1306, vua Trần Anh Tông gả em gái là công chúa Huyền Trân cho vua Chiêm Thành là Chế Mân; Chế Mân dâng hai châu Ô, Lý làm sính lễ.","Nhà Trần đổi tên thành châu Thuận, châu Hóa (vùng Quảng Trị, Thừa Thiên Huế ngày nay), mở rộng lãnh thổ về phía nam."],"lien":["vs56-trananhtong","nhantong","vs59-huyentran","vs59-trankhacchung"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 204"},{"id":"vs59-sk-1371","nam":1371,"bieu_tuong":"⚔","ten":"Chế Bồng Nga tiến vào Thăng Long","doan":["Dưới thời vua Chiêm Chế Bồng Nga, Chiêm Thành mạnh lên và nhiều lần tấn công Đại Việt; năm 1371 quân Chiêm vào tận Thăng Long cướp phá.","Các cuộc chiến kéo dài đến năm 1390, khi Chế Bồng Nga tử trận trên sông Hải Triều trong trận đánh với quân Trần do Trần Khát Chân chỉ huy."],"lien":["vs56-trannghetong","vs56-tranduetong","vs59-chebongnga"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 223"},{"id":"vs59-sk-1397","nam":1397,"bieu_tuong":"⚑","ten":"Cải cách của Hồ Quý Ly","doan":["Từ cuối thế kỉ XIV, Hồ Quý Ly nắm quyền và tiến hành nhiều cải cách: phát hành tiền giấy (1396), hạn điền, hạn nô, cải tổ thi cử, đề cao chữ Nôm.","Năm 1397, ông cho xây thành Tây Đô (Thanh Hóa) và năm 1400 lập ra nhà Hồ. Cải cách táo bạo nhưng chưa được lòng dân, góp phần làm nhà Hồ thất bại trước quân Minh."],"lien":["hoquyly","vs56-hohanthuong"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 231","hang":["Nhà Trần","Cuối thời Trần · Hồ Quý Ly nắm quyền","tran"]},{"id":"vs59-sk-1407","nam":1407,"bieu_tuong":"⚔","ten":"Nhà Hồ thất bại, quân Minh đô hộ","doan":["Cuối năm 1406, nhà Minh đem quân xâm lược. Thành Đa Bang thất thủ, quân Hồ thua ở Mộc Phàm Giang, Hàm Tử; giữa năm 1407 cha con Hồ Quý Ly bị bắt.","Đại Việt rơi vào ách đô hộ của nhà Minh hai mươi năm, chịu chính sách bóc lột và đồng hóa nặng nề."],"lien":["hoquyly","vs56-hohanthuong","vs56-honguyentrung"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 235"},{"id":"vs59-sk-1426","nam":1426,"bieu_tuong":"⚔","ten":"Trận Tốt Động – Chúc Động","doan":["Cuối năm 1426, nghĩa quân Lam Sơn phục kích và đánh tan đạo quân của Vương Thông ở Tốt Động – Chúc Động (Chương Mỹ, Hà Nội ngày nay).","Sau trận này, nghĩa quân vây hãm Đông Quan, quân Minh rơi vào thế bị động."],"lien":["leloi","nguyentrai"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 250","hang":["Khởi nghĩa Lam Sơn","1418–1427","lamson"]},{"id":"vs59-sk-1427","nam":1427,"bieu_tuong":"⚔","ten":"Trận Chi Lăng – Xương Giang","doan":["Tháng 10/1427, nghĩa quân Lam Sơn phục kích tại ải Chi Lăng, chém tướng Liễu Thăng, rồi tiêu diệt viện binh Minh ở Xương Giang.","Vương Thông ở Đông Quan phải xin hòa và rút quân về nước; đầu năm 1428 Lê Lợi lên ngôi, Nguyễn Trãi viết Bình Ngô đại cáo."],"lien":["leloi","nguyentrai","vs56-trannguyenhan","vs59-lieuthang","vs59-nguyenchich"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 251","hang":["Khởi nghĩa Lam Sơn","1418–1427","lamson"]},{"id":"vs59-sk-1442","nam":1442,"bieu_tuong":"⚑","ten":"Vụ án Lệ Chi Viên","doan":["Năm 1442, vua Lê Thái Tông đột ngột qua đời ở vườn vải Lệ Chi (Bắc Ninh) sau khi duyệt quân ở Chí Linh, nơi Nguyễn Trãi về ở.","Triều đình quy tội cho Nguyễn Trãi và người thiếp Nguyễn Thị Lộ, xử tru di ba họ. Năm 1464, vua Lê Thánh Tông minh oan cho Nguyễn Trãi."],"lien":["nguyentrai","vs56-lethaitong","lethanhtong","vs59-nguyenthilo"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 272"},{"id":"vs59-sk-1471","nam":1471,"bieu_tuong":"⚔","ten":"Lê Thánh Tông đánh Chiêm Thành","doan":["Năm 1471, Lê Thánh Tông thân chinh đánh Chiêm Thành, hạ kinh đô Đồ Bàn, bắt vua Chiêm là Trà Toàn.","Vùng đất phía bắc đèo Cù Mông được sáp nhập, lập thừa tuyên Quảng Nam; đây là lần mở rộng lãnh thổ lớn về phía nam."],"lien":["lethanhtong"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 280"},{"id":"vs59-sk-1527","nam":1527,"bieu_tuong":"⚑","ten":"Mạc Đăng Dung lập nhà Mạc","doan":["Đầu thế kỉ XVI, triều Lê suy yếu, các phe phái tranh giành quyền lực. Mạc Đăng Dung, một võ quan, dần nắm hết binh quyền.","Năm 1527, ông buộc vua Lê Cung Hoàng nhường ngôi, lập ra nhà Mạc, mở đầu thời kì chia cắt Nam – Bắc triều."],"lien":["macdangdung","vs56-lecunghoang"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 293"},{"id":"vs59-sk-1533","nam":1533,"bieu_tuong":"⚑","ten":"Nam triều – Bắc triều","doan":["Năm 1533, Nguyễn Kim lập con cháu nhà Lê là Lê Trang Tông ở vùng Thanh Hóa, Nghệ An, lấy danh nghĩa phù Lê diệt Mạc: sử gọi là Nam triều, còn nhà Mạc ở Thăng Long là Bắc triều.","Chiến tranh Nam – Bắc triều kéo dài hơn nửa thế kỉ; sau khi Nguyễn Kim mất, quyền hành Nam triều vào tay con rể là Trịnh Kiểm."],"lien":["vs56-nguyenkim","vs56-letrangtong","vs56-trinhkiem"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang)"},{"id":"vs59-sk-1558","nam":1558,"bieu_tuong":"⚑","ten":"Nguyễn Hoàng vào trấn thủ Thuận Hóa","doan":["Lo bị Trịnh Kiểm hãm hại, Nguyễn Hoàng (con thứ Nguyễn Kim) xin vào trấn thủ vùng Thuận Hóa năm 1558, sau kiêm cả Quảng Nam.","Từ đây, họ Nguyễn xây dựng cơ nghiệp ở phương Nam, mở đầu cho thời kì chúa Nguyễn ở Đàng Trong."],"lien":["vs56-nguyenhoang","vs56-trinhkiem"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 324","hang":["Lê trung hưng – chúa Trịnh, chúa Nguyễn","1533–1789","letrung"]},{"id":"vs59-sk-1592","nam":1592,"bieu_tuong":"⚔","ten":"Trịnh Tùng lấy lại Thăng Long","doan":["Năm 1592, Trịnh Tùng đem quân Nam triều tiến ra Bắc, đánh chiếm Thăng Long, bắt và giết vua Mạc Mậu Hợp.","Họ Mạc rút lên Cao Bằng giữ đất đến năm 1677. Nhà Lê trở lại Thăng Long nhưng thực quyền nằm trong tay họ Trịnh."],"lien":["trinhtung","vs56-macmauhop"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 318"},{"id":"vs59-sk-1627","nam":1627,"bieu_tuong":"⚔","ten":"Chiến tranh Trịnh – Nguyễn bùng nổ","doan":["Năm 1627, chúa Trịnh Tráng đem quân đánh chúa Nguyễn ở Đàng Trong, mở đầu cuộc chiến tranh Trịnh – Nguyễn.","Từ 1627 đến 1672 có bảy lần giao tranh lớn; chúa Nguyễn dựa vào hệ thống lũy Trường Dục, lũy Thầy (Đào Duy Từ đề xuất) để giữ đất."],"lien":["vs56-daoduytu"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 327"},{"id":"vs59-sk-1672","nam":1672,"bieu_tuong":"⚑","ten":"Sông Gianh thành ranh giới Đàng Trong – Đàng Ngoài","doan":["Sau lần giao tranh cuối năm 1672, hai bên không bên nào thắng nổi, đành ngừng chiến, lấy sông Gianh làm ranh giới.","Đất nước bị chia cắt khoảng một thế kỉ: Đàng Ngoài do chúa Trịnh, Đàng Trong do chúa Nguyễn cai quản."],"lien":[],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 338","hang":["Lê trung hưng – chúa Trịnh, chúa Nguyễn","1533–1789","letrung"]},{"id":"vs59-sk-1698","nam":1698,"bieu_tuong":"⚑","ten":"Lập phủ Gia Định","doan":["Năm 1698, chúa Nguyễn Phúc Chu sai Nguyễn Hữu Cảnh vào kinh lược đất Đồng Nai, lập phủ Gia Định với hai dinh Trấn Biên và Phiên Trấn.","Việc tổ chức hành chính đã xác lập quyền quản lí của chính quyền Đàng Trong ở vùng Nam Bộ."],"lien":["vs59-nguyenhuucanh"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang)","hang":["Lê trung hưng – chúa Trịnh, chúa Nguyễn","1533–1789","letrung"]},{"id":"vs59-sk-1771","nam":1771,"bieu_tuong":"✦","ten":"Khởi nghĩa Tây Sơn bùng nổ","doan":["Năm 1771, ba anh em Nguyễn Nhạc, Nguyễn Huệ, Nguyễn Lữ dựng cờ khởi nghĩa ở ấp Tây Sơn (Bình Định), chống lại chính quyền chúa Nguyễn đang mục nát.","Nghĩa quân lấy của nhà giàu chia cho dân nghèo, nhanh chóng lớn mạnh, chiếm được thành Quy Nhơn."],"lien":["nguyennhac","quangtrung"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang)"},{"id":"vs59-sk-1792","nam":1792,"bieu_tuong":"⚑","ten":"Vua Quang Trung qua đời","doan":["Sau chiến thắng quân Thanh, vua Quang Trung lo xây dựng đất nước: ban Chiếu khuyến nông, mở trường học, đề cao chữ Nôm, mở cửa buôn bán.","Năm 1792, ông đột ngột qua đời ở tuổi khoảng 40; con là Quang Toản còn nhỏ lên nối ngôi, triều Tây Sơn suy yếu dần."],"lien":["quangtrung","vs56-canhthinh","ngothinham"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 387"},{"id":"vs59-sk-1802","nam":1802,"bieu_tuong":"⚑","ten":"Nguyễn Ánh lập nhà Nguyễn","doan":["Năm 1802, Nguyễn Ánh lên ngôi ở Phú Xuân, đặt niên hiệu Gia Long, rồi đem quân ra Bắc đánh bại nhà Tây Sơn.","Năm 1804, đặt quốc hiệu là Việt Nam; nhà Nguyễn cai quản lãnh thổ từ Bắc vào Nam, đóng đô ở Huế."],"lien":["gialong"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 400"},{"id":"vs59-sk-1833","nam":1833,"bieu_tuong":"✦","ten":"Cuộc nổi dậy của Lê Văn Khôi","doan":["Năm 1833, Lê Văn Khôi chiếm thành Phiên An (Gia Định) chống lại triều Minh Mạng, được nhiều người ở Nam Kì hưởng ứng.","Quân triều đình vây thành gần ba năm mới chiếm lại được (1835). Cùng thời có các cuộc nổi dậy của Nông Văn Vân ở Cao Bằng, Phan Bá Vành ở Nam Định."],"lien":["minhmang","vs59-levankhoi","vs59-nongvanvan"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 421"},{"id":"vs59-sk-1838","nam":1838,"bieu_tuong":"⚑","ten":"Quốc hiệu Đại Nam","doan":["Năm 1838, vua Minh Mạng đổi quốc hiệu Việt Nam thành Đại Nam. Trước đó, những năm 1831–1832, ông chia cả nước thành 30 tỉnh và phủ Thừa Thiên.","Thời Minh Mạng, bộ máy nhà nước quân chủ tập quyền đạt đến mức chặt chẽ cao nhất của triều Nguyễn."],"lien":["minhmang"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang)"},{"id":"vs59-sk-1847","nam":1847,"bieu_tuong":"⚔","ten":"Pháp bắn phá Đà Nẵng lần đầu","doan":["Năm 1847, dưới thời vua Thiệu Trị, tàu chiến Pháp vào cửa Đà Nẵng, bắn chìm nhiều thuyền đồng của triều đình rồi bỏ đi.","Đây là cuộc đụng độ vũ trang đầu tiên giữa Pháp và nhà Nguyễn, báo trước cuộc xâm lược 11 năm sau."],"lien":["vs56-thieutri"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 428"},{"id":"vs59-sk-1861","nam":1861,"bieu_tuong":"⚔","ten":"Đại đồn Chí Hòa thất thủ","doan":["Tháng 2/1861, quân Pháp tấn công đại đồn Chí Hòa do Nguyễn Tri Phương chỉ huy; đồn vỡ, quân Pháp chiếm Định Tường, Biên Hòa, Vĩnh Long trong năm 1861–1862.","Cuối năm 1861, nghĩa quân Nguyễn Trung Trực đốt cháy tàu chiến Pháp Espérance trên vàm Nhật Tảo."],"lien":["nguyenphuong","vs56-tuduc","vs59-nguyentrungtruc","vs59-truongdinh"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 442"},{"id":"vs59-sk-1867","nam":1867,"bieu_tuong":"⚔","ten":"Pháp chiếm ba tỉnh miền Tây Nam Kì","doan":["Tháng 6/1867, quân Pháp chiếm Vĩnh Long, An Giang, Hà Tiên mà không gặp kháng cự lớn. Kinh lược sứ Phan Thanh Giản uống thuốc độc tự vẫn.","Toàn bộ Nam Kì trở thành thuộc địa của Pháp; phong trào kháng chiến của nhân dân vẫn tiếp tục."],"lien":["vs56-tuduc","vs59-phanthanhgian"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 445"},{"id":"vs59-sk-1873","nam":1873,"bieu_tuong":"⚔","ten":"Pháp đánh Bắc Kì lần thứ nhất","doan":["Tháng 11/1873, Francis Garnier đánh chiếm thành Hà Nội; Nguyễn Tri Phương bị thương, không chịu chữa và mất.","Ngày 21/12/1873, quân Cờ Đen của Lưu Vĩnh Phúc phối hợp với quân triều đình phục kích, giết Garnier ở Cầu Giấy. Năm 1874, triều Nguyễn kí Hòa ước Giáp Tuất."],"lien":["nguyenphuong","vs56-tuduc","vs59-hoangkeviem"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 451"},{"id":"vs59-sk-1882","nam":1882,"bieu_tuong":"⚔","ten":"Hà Nội thất thủ lần thứ hai","doan":["Tháng 4/1882, Henri Rivière đánh chiếm thành Hà Nội; Tổng đốc Hoàng Diệu tự vẫn để giữ khí tiết.","Ngày 19/5/1883, Rivière bị quân Cờ Đen phục kích giết ở Cầu Giấy. Pháp tăng viện, đánh thẳng vào Thuận An, buộc triều đình kí Hòa ước Quý Mùi (1883) và Patenôtre (1884)."],"lien":["vs56-hoangdieu","vs59-hoangkeviem"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 455"},{"id":"vs59-sk-1885","nam":1885,"bieu_tuong":"✦","ten":"Chiếu Cần Vương","doan":["Đêm 4 rạng 5/7/1885, phe chủ chiến do Tôn Thất Thuyết đứng đầu tấn công quân Pháp ở Huế nhưng thất bại. Ông đưa vua Hàm Nghi ra căn cứ Tân Sở (Quảng Trị) và xuống chiếu Cần Vương.","Văn thân, sĩ phu khắp nơi hưởng ứng: khởi nghĩa Ba Đình, Bãi Sậy, Hương Khê… Năm 1888 vua Hàm Nghi bị bắt và bị đày sang Algérie."],"lien":["vs56-hamnghi","vs56-tonthatthuyet","vs56-phandinhphung","vs59-dinhcongtrang","vs59-nguyenthienthuat","vs59-nguyenquangbich"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 465"},{"id":"vs59-sk-1896","nam":1896,"bieu_tuong":"✦","ten":"Khởi nghĩa Hương Khê kết thúc","doan":["Khởi nghĩa Hương Khê (Hà Tĩnh) do Phan Đình Phùng và Cao Thắng lãnh đạo kéo dài từ 1885 đến 1896, là cuộc khởi nghĩa lớn nhất của phong trào Cần Vương.","Nghĩa quân tự chế được súng theo mẫu của Pháp. Sau khi Phan Đình Phùng mất (12/1895), cuộc khởi nghĩa tan rã dần."],"lien":["vs56-phandinhphung","vs59-caothang"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 468"},{"id":"vs59-sk-1905","nam":1905,"bieu_tuong":"✦","ten":"Phong trào Đông Du","doan":["Năm 1905, Phan Bội Châu sang Nhật Bản, rồi đưa nhiều thanh niên Việt Nam sang học để chuẩn bị lực lượng cứu nước theo con đường bạo động.","Năm 1908–1909, Pháp cấu kết với Nhật trục xuất du học sinh, phong trào Đông Du tan rã."],"lien":["phanboichau","vs59-cuongde","vs59-dangthaithan"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 473","hang":["Việt Nam thuộc địa","1858–1945 · triều Nguyễn dưới chế độ bảo hộ","nguyenvn"]},{"id":"vs59-sk-1907","nam":1907,"bieu_tuong":"◈","ten":"Đông Kinh nghĩa thục","doan":["Năm 1907, Lương Văn Can, Nguyễn Quyền và các sĩ phu mở trường Đông Kinh nghĩa thục ở Hà Nội, dạy học miễn phí, truyền bá tư tưởng duy tân, cổ động chữ Quốc ngữ.","Trường hoạt động chưa đầy một năm thì bị Pháp đóng cửa. Năm 1908, phong trào chống thuế lan rộng ở Trung Kì."],"lien":["huynhthuckhang","vs59-luongvancan","vs59-phanchautrinh","vs59-tranquycap"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 474","hang":["Việt Nam thuộc địa","1858–1945 · triều Nguyễn dưới chế độ bảo hộ","nguyenvn"]},{"id":"vs59-sk-1916","nam":1916,"bieu_tuong":"✦","ten":"Vua Duy Tân mưu khởi nghĩa","doan":["Năm 1916, vua Duy Tân cùng Thái Phiên, Trần Cao Vân (Việt Nam Quang phục hội) bí mật chuẩn bị khởi nghĩa ở Trung Kì.","Kế hoạch bị lộ, vua bị bắt và đày sang đảo Réunion; Thái Phiên, Trần Cao Vân bị xử tử."],"lien":["vs56-duytan","vs59-thaiphien","vs59-trancaovan"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 478","hang":["Việt Nam thuộc địa","1858–1945 · triều Nguyễn dưới chế độ bảo hộ","nguyenvn"]},{"id":"vs59-sk-1930","nam":1930,"bieu_tuong":"✦","ten":"Khởi nghĩa Yên Bái","doan":["Đêm 9/2/1930, Việt Nam Quốc dân đảng do Nguyễn Thái Học lãnh đạo khởi nghĩa ở Yên Bái và một số nơi, nhưng nhanh chóng bị đàn áp.","Nguyễn Thái Học cùng 12 đồng chí bị xử chém ở Yên Bái tháng 6/1930. Cùng năm, phong trào cách mạng 1930–1931 bùng lên, đỉnh cao là Xô viết Nghệ – Tĩnh."],"lien":["vs59-nguyenthaihoc"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 487","hang":["Việt Nam thuộc địa","1858–1945 · triều Nguyễn dưới chế độ bảo hộ","nguyenvn"]},{"id":"vs59-sk-1940","nam":1940,"bieu_tuong":"⚔","ten":"Nhật vào Đông Dương, khởi nghĩa Bắc Sơn và Nam Kì","doan":["Tháng 9/1940, quân Nhật tiến vào Đông Dương; nhân dân chịu cảnh “một cổ hai tròng” Pháp – Nhật.","Cuối năm 1940 nổ ra khởi nghĩa Bắc Sơn (27/9) và khởi nghĩa Nam Kì (23/11); cả hai đều bị đàn áp nhưng để lại bài học về khởi nghĩa vũ trang."],"lien":["vs59-nguyenvancu","vs59-phungchikien","vs59-nguyenthiminhkhai","vs59-vovantan"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang), tr. PDF 487","hang":["Việt Nam thuộc địa","1858–1945 · triều Nguyễn dưới chế độ bảo hộ","nguyenvn"]},{"id":"vs59-sk-1945","nam":1945,"bieu_tuong":"⚑","ten":"Nhật đảo chính Pháp","doan":["Đêm 9/3/1945, Nhật đảo chính lật đổ Pháp ở Đông Dương, dựng chính phủ Trần Trọng Kim dưới danh nghĩa Đế quốc Việt Nam.","Nạn đói đầu năm 1945 làm khoảng hai triệu người chết ở miền Bắc. Tháng 8/1945, Nhật đầu hàng Đồng minh, Tổng khởi nghĩa giành chính quyền thắng lợi trên cả nước."],"lien":["hochiminh","vs56-baodai","vs59-trantrongkim"],"src":"Phạm Văn Sơn, Việt sử toàn thư (bản điện tử 520 trang)"}],"hcm":[{"nam":1890,"ngay":"19/5/1890","ten":"Ra đời ở quê ngoại Hoàng Trù","trang":9,"doan":["Nguyễn Sinh Cung sinh ngày 19/5/1890 tại quê ngoại làng Hoàng Trù (làng Trùa), nay thuộc xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An, trong một gia đình nhà nho gốc nông dân.","Cha là Nguyễn Sinh Sắc (1862–1929), mồ côi sớm, được nhà nho Hoàng Xuân Đường nuôi dạy và gả con gái, về sau đỗ Phó bảng. Mẹ là Hoàng Thị Loan (1868–1901), làm ruộng, dệt vải, hết lòng chăm lo chồng con.","Chị gái Nguyễn Thị Thanh và anh trai Nguyễn Sinh Khiêm đều tham gia phong trào yêu nước, bị tù đày. Đến năm lên 5, cậu bé sống ở quê, ham hiểu biết, thích nghe bà ngoại và mẹ kể chuyện."]},{"nam":1895,"ngay":"1895–1901","ten":"Những năm đầu ở kinh thành Huế","trang":12,"doan":["Năm 1895, Nguyễn Sinh Cung theo cha mẹ vào Huế khi ông Sắc vào kinh dự thi Hội. Gia đình ở nhờ trong thành nội (nay là số 112 đường Mai Thúc Loan), cuộc sống rất chật vật: mẹ dệt vải, cha đi chép chữ thuê.","Cuối năm 1898, ông Sắc về dạy học ở làng Dương Nỗ (Phú Vang); cậu bé theo cha và bắt đầu học chữ Hán.","Ở Huế, cậu thấy rõ cảnh người Pháp hống hách, quan lại khúm núm và người lao động cực khổ. Những hình ảnh ấy in sâu trong kí ức tuổi thơ."]},{"nam":1901,"ngay":"1901","ten":"Mất mẹ, mang tên Nguyễn Tất Thành","trang":14,"doan":["Đầu năm 1901, bà Hoàng Thị Loan sinh em bé Xin rồi lâm bệnh qua đời ở Huế; ít lâu sau em bé cũng mất. Mới 11 tuổi, Nguyễn Sinh Cung chịu nỗi đau mất mẹ và em.","Tháng 5/1901, ông Nguyễn Sinh Huy (tên mới của ông Sắc) đỗ Phó bảng. Khoảng tháng 9/1901 gia đình về quê nội Kim Liên; trong lễ vào làng, hai anh em được đặt tên mới là Nguyễn Tất Đạt và Nguyễn Tất Thành.","Ở quê, Nguyễn Tất Thành học chữ Hán với các thầy giáo yêu nước, được nghe các sĩ phu như Phan Bội Châu bàn chuyện thời cuộc, sớm thấm thía cảnh nước mất nhà tan."]},{"nam":1906,"ngay":"1905–1907","ten":"Học trường Pháp – Việt","trang":16,"doan":["Năm 1903–1904, Nguyễn Tất Thành theo cha đến dạy học ở Thanh Chương (Nghệ An) rồi Đức Thọ (Hà Tĩnh), đi thăm nhiều di tích yêu nước. Khoảng tháng 9/1905, anh vào lớp dự bị Trường tiểu học Pháp – bản xứ ở Vinh, lần đầu tiếp xúc với khẩu hiệu Tự do – Bình đẳng – Bác ái.","Cuối tháng 5/1906, ông Nguyễn Sinh Huy vào Huế nhận chức; hai anh em theo cha vào kinh và học Trường tiểu học Pháp – Việt tỉnh Thừa Thiên."]},{"nam":1908,"ngay":"4/1908","ten":"Biểu tình chống thuế, học Quốc học Huế","trang":17,"doan":["Tháng 4/1908, Nguyễn Tất Thành tham gia cuộc biểu tình chống thuế của nông dân Thừa Thiên, từ đó bị mật thám Pháp theo dõi; cha anh cũng bị khiển trách.","Tháng 8/1908, với tên Nguyễn Sinh Côn, anh vẫn được nhận vào Trường Quốc học Huế. Qua các thầy giáo yêu nước và sách báo tiến bộ, ý định sang phương Tây tìm hiểu văn minh các nước lớn dần trong anh."]},{"nam":1910,"ngay":"1909–1911","ten":"Bình Khê, Quy Nhơn, Phan Thiết, Sài Gòn","trang":18,"doan":["Giữa năm 1909, anh theo cha vào Bình Định khi ông làm Tri huyện Bình Khê, rồi học tiếp ở Trường tiểu học Pháp – Việt Quy Nhơn, hoàn thành bậc tiểu học tháng 6/1910.","Khi cha bị cách chức, anh không về Huế mà đi tiếp vào Nam, dừng ở Phan Thiết làm trợ giáo ở Trường Dục Thanh, đọc nhiều sách trong tủ sách của nhân sĩ Nguyễn Thông.","Tháng 2/1911, anh vào Sài Gòn, ở nhờ các chi nhánh của Liên Thành công ty, tìm cách xin việc trên các tàu biển để được đi xa."]},{"nam":1911,"ngay":"05/6/1911","ten":"Ra đi tìm đường cứu nước","trang":22,"doan":["Ngày 3/6/1911, lấy tên Văn Ba, Nguyễn Tất Thành xin làm phụ bếp trên tàu Đô đốc Latouche-Tréville của hãng Năm Sao. Ngày 5/6/1911, con tàu rời cảng Sài Gòn (bến Nhà Rồng) đi Mác-xây.","Tàu dừng ở Mác-xây và Lơ Ha-vơ-rơ. Những ngày đầu trên đất Pháp, anh nhận ra ở Pháp cũng có người nghèo, và nhiều người Pháp ở chính quốc tốt hơn bọn thực dân ở thuộc địa."]},{"nam":1912,"ngay":"cuối 1912","ten":"Sang nước Mỹ","trang":24,"doan":["Theo các chuyến tàu, Nguyễn Tất Thành đi qua Mác-ti-ních, U-ru-goay, Ác-hen-ti-na và đến nước Mỹ vào cuối năm 1912.","Ở Mỹ, anh làm thuê để sống, tìm hiểu đời sống của người lao động và của người da đen."]},{"nam":1913,"ngay":"1913–1917","ten":"Làm thuê và học tiếng Anh ở Luân Đôn","trang":26,"doan":["Đầu năm 1913, anh trở lại Pháp rồi sang Anh, làm cào tuyết, đốt lò, rồi phụ bếp ở các khách sạn Drayton Court và Carlton (Luân Đôn), tranh thủ học tiếng Anh.","Anh viết thư cho cụ Phan Châu Trinh ở Pháp, tham gia Hội những người lao động hải ngoại, theo dõi phong trào đấu tranh của nhân dân Ai-len."]},{"nam":1917,"ngay":"cuối 1917","ten":"Trở lại nước Pháp","trang":28,"doan":["Khoảng cuối năm 1917, giữa lúc Chiến tranh thế giới thứ nhất diễn ra ác liệt, Nguyễn Tất Thành từ Anh trở lại Pháp, sống ở Pa-ri để trực tiếp hoạt động trong cộng đồng người Việt.","Đầu năm 1919, anh gia nhập Đảng Xã hội Pháp vì đó là tổ chức theo đuổi lí tưởng Tự do – Bình đẳng – Bác ái."]},{"nam":1919,"ngay":"18/6/1919","ten":"Bản yêu sách của nhân dân An Nam","trang":30,"doan":["Nhân Hội nghị Véc-xai, Nguyễn Tất Thành thay mặt Hội những người Việt Nam yêu nước gửi bản Yêu sách của nhân dân An Nam gồm tám điểm, kí tên Nguyễn Ái Quốc.","Yêu sách đòi các quyền tự do, dân chủ tối thiểu cho người dân Đông Dương. Tuy không được đáp ứng, sự kiện đã gây tiếng vang lớn và khiến tên Nguyễn Ái Quốc được nhiều người biết đến."]},{"nam":1920,"ngay":"12/1920","ten":"Đại hội Tours – người cộng sản Việt Nam đầu tiên","trang":36,"doan":["Tháng 7/1920, Nguyễn Ái Quốc đọc Luận cương của Lê-nin về vấn đề dân tộc và thuộc địa, tìm thấy con đường giải phóng dân tộc.","Tại Đại hội Tours của Đảng Xã hội Pháp, chiều 26/12/1920 Người phát biểu tố cáo chủ nghĩa thực dân, rồi bỏ phiếu tán thành Quốc tế Cộng sản, tham gia thành lập Đảng Cộng sản Pháp."]},{"nam":1921,"ngay":"1921–1923","ten":"Hội Liên hiệp thuộc địa và báo Le Paria","trang":53,"doan":["Năm 1921, Nguyễn Ái Quốc cùng các chiến sĩ chống thực dân ở Pa-ri thành lập Hội Liên hiệp thuộc địa và được bầu vào Ban Chấp hành. Người sống trong căn phòng 9 m² ở ngõ Công-poanh, quận 17.","Năm 1922, Hội ra báo Le Paria (Người cùng khổ). Người vừa làm chủ nhiệm, chủ bút vừa viết bài, vẽ tranh, tự đi bán báo, đồng thời dự Đại hội I Đảng Cộng sản Pháp (12/1921)."]},{"nam":1923,"ngay":"1923–1924","ten":"Ở Liên Xô","trang":58,"doan":["Giữa năm 1923, Nguyễn Ái Quốc rời Pháp sang Liên Xô. Tháng 10/1923, Người dự Hội nghị Quốc tế Nông dân và được bầu vào Ban Chấp hành.","Tháng 1/1924, Lê-nin qua đời; Người viết bài “Lê-nin và các dân tộc thuộc địa”. Tại Đại hội V Quốc tế Cộng sản (6–7/1924), Người phát biểu nhiều lần về vấn đề thuộc địa và ruộng đất."]},{"nam":1924,"ngay":"11/11/1924","ten":"Đến Quảng Châu","trang":73,"doan":["Cuối tháng 10/1924, Nguyễn Ái Quốc rời Mát-xcơ-va, đi xuyên Xi-bê-ri và đến Quảng Châu ngày 11/11/1924, với danh nghĩa phiên dịch cho phái đoàn cố vấn Liên Xô.","Cuối năm 1924, bản thảo Bản án chế độ thực dân Pháp được gửi về Pa-ri; sách in năm 1925."]},{"nam":1925,"ngay":"6/1925","ten":"Hội Việt Nam Cách mạng Thanh niên","trang":75,"doan":["Tháng 6/1925, Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên, với hạt nhân là Cộng sản đoàn; ra báo Thanh niên.","Người trực tiếp mở các lớp huấn luyện chính trị ở Quảng Châu cho thanh niên từ trong nước sang, đào tạo cán bộ để đưa chủ nghĩa Mác – Lê-nin về Việt Nam."]},{"nam":1927,"ngay":"1927","ten":"Đường Kách mệnh, rời Quảng Châu","trang":84,"doan":["Đầu năm 1927, những bài giảng của Người được in thành sách Đường Kách mệnh.","Sau cuộc đảo chính của Tưởng Giới Thạch (4/1927), Người phải rời Quảng Châu; tháng 5/1927 trở lại Mát-xcơ-va, sau đó sang Đức, Bỉ, I-ta-li-a."]},{"nam":1928,"ngay":"7/1928–11/1929","ten":"Hoạt động ở Xiêm","trang":86,"doan":["Đầu tháng 6/1928, Người rời Béc-lin, qua Thụy Sĩ, I-ta-li-a để về gần Tổ quốc.","Từ tháng 7/1928 đến tháng 11/1929, với tên Thầu Chín, Người hoạt động trong cộng đồng Việt kiều ở Xiêm (Thái Lan), xây dựng lực lượng cách mạng, mở lớp học, ra báo."]},{"nam":1930,"ngay":"3/2/1930","ten":"Thành lập Đảng Cộng sản Việt Nam","trang":95,"doan":["Năm 1929 ở trong nước có ba tổ chức cộng sản. Đầu năm 1930, Người chủ trì hội nghị hợp nhất tại Cửu Long (gần Hương Cảng), từ ngày 3/2/1930, thành lập Đảng Cộng sản Việt Nam.","Hội nghị thông qua Chính cương vắn tắt, Sách lược vắn tắt, Điều lệ do Người soạn. Người viết Lời kêu gọi nhân dịp thành lập Đảng."]},{"nam":1931,"ngay":"6/6/1931","ten":"Bị bắt ở Hương Cảng","trang":108,"doan":["Ngày 6/6/1931, với tên Tống Văn Sơ, Nguyễn Ái Quốc bị cảnh sát Anh bắt ở Hương Cảng; thực dân Pháp tìm cách đòi dẫn độ.","Qua Quốc tế Cứu tế đỏ, luật sư người Anh Lô-dơ-bi (F. H. Loseby) đứng ra bào chữa và giúp Người thoát khỏi nhà tù. Năm 1933 Người rời Hạ Môn lên Thượng Hải, rồi sang Liên Xô (6/1934)."]},{"nam":1934,"ngay":"10/1934","ten":"Học Trường Quốc tế Lê-nin","trang":113,"doan":["Tháng 10/1934, Nguyễn Ái Quốc vào học Trường Quốc tế Lê-nin ở Mát-xcơ-va với bí danh Lin.","Năm 1935, Người dự Đại hội VII Quốc tế Cộng sản với tư cách tham dự, rồi dặn Lê Hồng Phong sớm về nước truyền đạt nghị quyết của Đại hội."]},{"nam":1938,"ngay":"10/1938","ten":"Trở về phương Đông","trang":119,"doan":["Đầu tháng 10/1938, Người rời Mát-xcơ-va về Trung Quốc, đi qua U-rum-xi, Lan Châu, Diên An; hoạt động trong Bát lộ quân với tên Hồ Quang.","Từ năm 1939, Người viết nhiều báo cáo gửi Quốc tế Cộng sản và loạt bài “Thư từ Trung Quốc”, tìm cách liên lạc với Đảng ở trong nước."]},{"nam":1941,"ngay":"28/1/1941","ten":"Về nước, Hội nghị Trung ương 8","trang":131,"doan":["Ngày 28/1/1941, sau 30 năm xa Tổ quốc, Người về nước, ở và làm việc tại Pác Bó (Cao Bằng).","Từ ngày 10 đến 19/5/1941, Người chủ trì Hội nghị Trung ương 8, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, thành lập Mặt trận Việt Minh. Ngày 6/6/1941 Người viết thư Kính cáo đồng bào."]},{"nam":1942,"ngay":"13/8/1942","ten":"Bị bắt ở Quảng Tây – Nhật kí trong tù","trang":140,"doan":["Ngày 13/8/1942, lấy tên Hồ Chí Minh, Người sang Trung Quốc tìm sự liên minh quốc tế thì bị chính quyền Tưởng Giới Thạch bắt, giải qua nhiều nhà lao ở Quảng Tây.","Trong tù, Người viết tập thơ Ngục trung nhật kí. Ngày 10/9/1943 Người được trả tự do nhưng vẫn bị quản chế, kiên trì tập luyện để hồi phục sức khỏe."]},{"nam":1944,"ngay":"22/12/1944","ten":"Đội Việt Nam Tuyên truyền Giải phóng quân","trang":146,"doan":["Tháng 9/1944, Hồ Chí Minh về Pác Bó, đề nghị hoãn kế hoạch khởi nghĩa vội vàng ở Cao – Bắc – Lạng.","Theo chỉ thị của Người, ngày 22/12/1944 Đội Việt Nam Tuyên truyền Giải phóng quân ra đời do Võ Nguyên Giáp chỉ huy, tiền thân của Quân đội nhân dân Việt Nam."]},{"nam":1945,"ngay":"2/9/1945","ten":"Tổng khởi nghĩa và Tuyên ngôn Độc lập","trang":149,"doan":["Sau ngày Nhật đảo chính Pháp (9/3/1945), đầu tháng 5/1945 Người chuyển về Tân Trào (Tuyên Quang). Ngày 16–17/8/1945, Quốc dân Đại hội Tân Trào tán thành Tổng khởi nghĩa và bầu Ủy ban dân tộc giải phóng do Người làm Chủ tịch.","Ngày 23/8/1945 Người về Hà Nội. Ngày 2/9/1945, tại Quảng trường Ba Đình, Người đọc Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa."]},{"nam":1946,"ngay":"1946","ten":"Năm 1946 – giữ vững chính quyền non trẻ","trang":167,"doan":["Ngày 6/1/1946 cả nước Tổng tuyển cử; Quốc hội khóa I bầu Người làm Chủ tịch nước. Ngày 6/3/1946 kí Hiệp định Sơ bộ; ngày 24/3/1946 gặp Đác-giăng-li-ơ trên vịnh Hạ Long.","Từ 31/5 đến 20/10/1946, Người thăm chính thức nước Pháp, kí Tạm ước 14/9. Khi thực dân Pháp bội ước, ngày 19/12/1946 Người ra Lời kêu gọi toàn quốc kháng chiến rồi lên chiến khu Việt Bắc."]},{"nam":1950,"ngay":"1/1950","ten":"Ngoại giao phá thế bao vây","trang":208,"doan":["Ngày 14/1/1950, Người tuyên bố Chính phủ Việt Nam Dân chủ Cộng hòa sẵn sàng đặt quan hệ ngoại giao với mọi nước. Trung Quốc (18/1), Liên Xô (30/1) và các nước dân chủ nhân dân lần lượt công nhận.","Đầu năm 1950, Người bí mật đi Bắc Kinh và Mát-xcơ-va. Mùa thu 1950, Người trực tiếp ra mặt trận Chiến dịch Biên giới."]},{"nam":1951,"ngay":"2/1951","ten":"Đại hội II của Đảng","trang":211,"doan":["Từ ngày 11 đến 19/2/1951, Đại hội II của Đảng họp ở Chiêm Hóa (Tuyên Quang). Đảng ra hoạt động công khai với tên Đảng Lao động Việt Nam.","Người được bầu làm Chủ tịch Ban Chấp hành Trung ương Đảng."]},{"nam":1954,"ngay":"7/5/1954","ten":"Điện Biên Phủ – Giơ-ne-vơ","trang":228,"doan":["Ngày 6/12/1953, Người cùng Bộ Chính trị quyết định mở chiến dịch Điện Biên Phủ. Ngày 13/3/1954 quân ta tiến công; ngày 7/5/1954 toàn bộ tập đoàn cứ điểm bị tiêu diệt.","Hội nghị Giơ-ne-vơ khai mạc ngày 8/5/1954; Hiệp định kí ngày 21/7/1954. Ngày 14/10/1954 Người về Hà Nội; ngày 1/1/1955, 25 vạn người dân Thủ đô mít tinh ở Ba Đình đón Trung ương Đảng, Chính phủ và Bác Hồ."]},{"nam":1960,"ngay":"1960","ten":"Hiến pháp mới, Đại hội III","trang":252,"doan":["Ngày 1/1/1960, Người kí sắc lệnh công bố Hiến pháp mới. Tối 5/1/1960, Người đọc diễn văn kỉ niệm 30 năm thành lập Đảng.","Tháng 9/1960, Đại hội III của Đảng bầu lại Người làm Chủ tịch Ban Chấp hành Trung ương; Quốc hội khóa II bầu Người làm Chủ tịch nước."]},{"nam":1965,"ngay":"10/5/1965","ten":"Bắt đầu viết Di chúc","trang":306,"doan":["Ngày 10/5/1965, Người bắt đầu viết bản Di chúc, những năm sau còn xem lại, bổ sung: năm 1966 thêm câu về tình đồng chí thương yêu lẫn nhau; năm 1968 viết thêm một số đoạn.","Ngày 10/5/1969, Người viết lại toàn bộ phần mở đầu; bản Di chúc được hoàn tất."]},{"nam":1966,"ngay":"17/7/1966","ten":"“Không có gì quý hơn độc lập, tự do”","trang":279,"doan":["Ngày 17/7/1966, trong Lời kêu gọi đồng bào và chiến sĩ cả nước chống Mỹ, cứu nước, Người nêu chân lí: Không có gì quý hơn độc lập, tự do.","Cùng năm, Người gửi thư tới các nước liên quan Hiệp định Giơ-ne-vơ và nhân dân thế giới, kêu gọi ủng hộ cuộc đấu tranh chính nghĩa của Việt Nam."]},{"nam":1969,"ngay":"2/9/1969","ten":"Chủ tịch Hồ Chí Minh qua đời","trang":306,"doan":["Tết 1969 Người còn vui văn nghệ cùng cán bộ phục vụ; ngày 19/5/1969 còn viết thư khen các cháu thiếu niên chăm trâu bò. Tháng 8/1969 Người lâm bệnh nặng.","Người qua đời lúc 9 giờ 47 phút ngày 2/9/1969. Ngày 9/9/1969 Lễ truy điệu được tổ chức trọng thể ở Hà Nội; đồng chí Lê Duẩn đọc Điếu văn."]},{"nam":1970,"ngay":"1970–1978","ten":"Thực hiện Di chúc","trang":312,"doan":["Ngày 6/3/1970, Bộ Chính trị mở cuộc vận động nâng cao chất lượng đảng viên và kết nạp lớp đảng viên Hồ Chí Minh.","Ngày 29/8/1975, Lăng Chủ tịch Hồ Chí Minh khánh thành. Năm 1977 Bộ Chính trị quyết định xây dựng Bảo tàng Hồ Chí Minh; năm 1978 quyết định xuất bản Hồ Chí Minh Tuyển tập và Toàn tập."]},{"nam":1975,"ngay":"30/4/1975","ten":"Thống nhất đất nước","trang":314,"doan":["Chiến dịch mang tên Hồ Chí Minh kết thúc thắng lợi ngày 30/4/1975, thực hiện mong ước thống nhất Tổ quốc mà Người gửi gắm trong Di chúc.","Năm 1976, thành phố Sài Gòn – Gia Định được mang tên Thành phố Hồ Chí Minh."]},{"nam":1987,"ngay":"1987","ten":"UNESCO tôn vinh","trang":324,"doan":["Năm 1987, UNESCO ra nghị quyết tôn vinh Hồ Chí Minh là Anh hùng giải phóng dân tộc Việt Nam và nhà văn hóa kiệt xuất, khuyến nghị kỉ niệm 100 năm ngày sinh của Người.","Năm 1990, nhiều nước trên thế giới tổ chức kỉ niệm; Bảo tàng Hồ Chí Minh ở Hà Nội khánh thành ngày 19/5/1990."]}],"hcm_nguon":"Hồ Chí Minh – Tiểu sử (Bảo tàng Hồ Chí Minh; Chu Đức Tính chủ biên; NXB Chính trị quốc gia, tái bản 2017)","hcm_ho_so":["Chủ tịch Hồ Chí Minh (19/5/1890 – 2/9/1969), lúc nhỏ tên Nguyễn Sinh Cung, khi đi học tên Nguyễn Tất Thành, nhiều năm hoạt động cách mạng lấy tên Nguyễn Ái Quốc; quê làng Kim Liên, huyện Nam Đàn, tỉnh Nghệ An.","Năm 1911, Người ra nước ngoài tìm đường cứu nước; năm 1920 tham gia thành lập Đảng Cộng sản Pháp; năm 1925 lập Hội Việt Nam Cách mạng Thanh niên; ngày 3/2/1930 chủ trì hội nghị thành lập Đảng Cộng sản Việt Nam.","Năm 1941, Người về nước lãnh đạo cách mạng, thành lập Mặt trận Việt Minh; ngày 2/9/1945 đọc Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa và được Quốc hội bầu làm Chủ tịch nước (1946).","Người lãnh đạo cuộc kháng chiến chống Pháp (1946–1954), sự nghiệp xây dựng miền Bắc và kháng chiến chống Mĩ; được bầu làm Chủ tịch Ban Chấp hành Trung ương Đảng tại Đại hội II (1951) và Đại hội III (1960).","Theo cuốn Hồ Chí Minh – Tiểu sử của Bảo tàng Hồ Chí Minh, Người là người sáng lập Đảng, Mặt trận dân tộc thống nhất, lực lượng vũ trang nhân dân và nước Việt Nam Dân chủ Cộng hòa; năm 1987 UNESCO tôn vinh Người là Anh hùng giải phóng dân tộc, nhà văn hóa kiệt xuất. Xem thêm mục Chủ tịch Hồ Chí Minh trên menu."],"hcm_bai_viet":[{"chang":1890,"ten":"Thời niên thiếu (1890–1911)","trang":"9–21","doan":["Nguyễn Sinh Cung lớn lên ở xứ Nghệ, vùng quê giàu truyền thống hiếu học và chống ngoại xâm, trong một gia đình nhà nho nghèo gốc nông dân. Cha là Phó bảng Nguyễn Sinh Sắc dạy các con ý thức lao động và đạo lí làm người; mẹ là bà Hoàng Thị Loan cần mẫn, đôn hậu.","Khoảng mười năm sống ở kinh thành Huế (1895–1901, 1906–1909) giúp cậu thấy rõ sự tương phản giữa kẻ thống trị và người lao động, đồng thời tiếp xúc với văn hóa mới. Cậu học chữ Hán, rồi học trường Pháp – Việt và Quốc học Huế, lần đầu biết đến khẩu hiệu Tự do – Bình đẳng – Bác ái.","Năm 1908, anh tham gia biểu tình chống thuế ở Thừa Thiên; từ đó bị mật thám theo dõi. Anh theo cha vào Bình Định, học ở Quy Nhơn, rồi làm trợ giáo Trường Dục Thanh (Phan Thiết).","Nhìn lại các phong trào Cần vương, Đông Du, Đông Kinh nghĩa thục, khởi nghĩa Yên Thế… anh khâm phục các bậc tiền bối nhưng nhận thấy những con đường ấy chưa đưa được dân tộc đến độc lập. Anh quyết định sang phương Tây tìm hiểu, và đầu năm 1911 vào Sài Gòn chuẩn bị ra đi."]},{"chang":1911,"ten":"Tìm đường cứu nước (1911–1920)","trang":"22–42","doan":["Ngày 5/6/1911, Nguyễn Tất Thành rời Sài Gòn trên tàu Đô đốc Latouche-Tréville. Trong nhiều năm, anh làm phụ bếp, cào tuyết, đốt lò… đi qua nhiều nước châu Âu, châu Phi, châu Mỹ; sống ở Mỹ (cuối 1912), Anh (1913–1917).","Cuộc sống lao động giúp anh thấy ở đâu người lao động cũng bị áp bức, và nhân dân các nước thuộc địa đều có chung kẻ thù là chủ nghĩa đế quốc.","Cuối năm 1917 anh trở về Pa-ri, hoạt động trong Hội những người Việt Nam yêu nước, vào Đảng Xã hội Pháp (1919). Ngày 18/6/1919 anh gửi Yêu sách của nhân dân An Nam tới Hội nghị Véc-xai, kí tên Nguyễn Ái Quốc.","Tháng 7/1920, đọc Luận cương của Lê-nin, Người tìm thấy con đường cứu nước. Tháng 12/1920, tại Đại hội Tours, Người tán thành Quốc tế Cộng sản, tham gia lập Đảng Cộng sản Pháp — bước chuyển từ chủ nghĩa yêu nước đến chủ nghĩa Mác – Lê-nin."]},{"chang":1924,"ten":"Chuẩn bị thành lập Đảng và hoạt động ở nước ngoài (1920–1941)","trang":"43–148","doan":["Ở Pháp (1921–1923), Nguyễn Ái Quốc lập Hội Liên hiệp thuộc địa, ra báo Le Paria, viết nhiều bài tố cáo chủ nghĩa thực dân. Ở Liên Xô (1923–1924), Người làm việc ở Quốc tế Nông dân, dự Đại hội V Quốc tế Cộng sản.","Đến Quảng Châu (11/1924), Người lập Hội Việt Nam Cách mạng Thanh niên (6/1925), mở lớp huấn luyện cán bộ, ra báo Thanh niên; các bài giảng in thành Đường Kách mệnh (1927). Bản án chế độ thực dân Pháp xuất bản ở Pa-ri năm 1925.","Sau thời gian ở Liên Xô, châu Âu và Xiêm (1928–1929), đầu năm 1930 Người chủ trì hội nghị hợp nhất ba tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam.","Những năm 1930–1940 là thời kì rất gian khổ: Người bị bắt ở Hương Cảng (1931), được luật sư Lô-dơ-bi cứu; học ở Trường Quốc tế Lê-nin (1934), rồi về Trung Quốc (1938), tìm đường về nước."]},{"chang":1941,"ten":"Về nước lãnh đạo cách mạng (1941–1945)","trang":"125–166","doan":["Ngày 28/1/1941 Người về nước ở Pác Bó. Hội nghị Trung ương 8 (5/1941) do Người chủ trì đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, lập Mặt trận Việt Minh, xây dựng lực lượng vũ trang và căn cứ địa.","Tháng 8/1942 Người sang Trung Quốc và bị giam hơn một năm; Nhật kí trong tù ra đời trong hoàn cảnh ấy. Về nước, Người chỉ thị lập Đội Việt Nam Tuyên truyền Giải phóng quân (22/12/1944).","Sau khi Nhật đảo chính Pháp (9/3/1945), Người về Tân Trào (5/1945), lập Khu giải phóng. Khi Nhật đầu hàng, Hội nghị toàn quốc của Đảng và Quốc dân Đại hội Tân Trào (16–17/8/1945) quyết định Tổng khởi nghĩa.","Chỉ trong khoảng nửa tháng, chính quyền về tay nhân dân trên cả nước. Ngày 2/9/1945, Người đọc Tuyên ngôn Độc lập tại Ba Đình."]},{"chang":1945,"ten":"Lãnh đạo kháng chiến, kiến quốc (1945–1954)","trang":"167–234","doan":["Chính quyền non trẻ đối mặt với giặc đói, giặc dốt, giặc ngoại xâm. Người tổ chức Tổng tuyển cử (6/1/1946), Hiến pháp đầu tiên, phong trào diệt giặc đói, giặc dốt; dùng sách lược hòa hoãn để có thời gian chuẩn bị (Hiệp định Sơ bộ 6/3, Tạm ước 14/9/1946).","Ngày 19/12/1946 Người ra Lời kêu gọi toàn quốc kháng chiến, rồi lên Việt Bắc lãnh đạo cuộc kháng chiến toàn dân, toàn diện, lâu dài, dựa vào sức mình là chính.","Năm 1950 các nước xã hội chủ nghĩa công nhận Việt Nam Dân chủ Cộng hòa; Người trực tiếp ra mặt trận Biên giới. Đại hội II (2/1951) bầu Người làm Chủ tịch Đảng.","Người cùng Bộ Chính trị quyết định mở chiến dịch Điện Biên Phủ (12/1953). Chiến thắng ngày 7/5/1954 dẫn tới Hiệp định Giơ-ne-vơ, miền Bắc được giải phóng."]},{"chang":1954,"ten":"Xây dựng miền Bắc, đấu tranh thống nhất (1954–1969)","trang":"235–311","doan":["Trở về Hà Nội (10/1954), Người lãnh đạo khôi phục kinh tế, cải tạo và xây dựng miền Bắc, đồng thời đấu tranh đòi thi hành Hiệp định Giơ-ne-vơ.","Người công bố Hiến pháp năm 1959 (1/1/1960), chủ trì Đại hội III (9/1960) đề ra hai nhiệm vụ chiến lược ở hai miền. Người thường xuyên đi thăm các địa phương, nhà máy, hợp tác xã, quan tâm đồng bào miền núi và thiếu nhi.","Khi Mỹ đưa quân vào miền Nam và đánh phá miền Bắc, Người kêu gọi cả nước quyết tâm chống Mỹ, cứu nước với chân lí “Không có gì quý hơn độc lập, tự do” (17/7/1966), đồng thời tranh thủ sự ủng hộ của nhân dân thế giới.","Từ năm 1965, Người viết và chỉnh sửa bản Di chúc. Người qua đời ngày 2/9/1969 khi sự nghiệp thống nhất đất nước chưa hoàn thành."]},{"chang":1969,"ten":"Sống mãi với non sông đất nước (1969–nay)","trang":"312–328","doan":["Thực hiện Di chúc, toàn Đảng, toàn dân đẩy mạnh kháng chiến chống Mỹ, giải phóng miền Nam, thống nhất đất nước (30/4/1975); cuộc vận động lớp đảng viên Hồ Chí Minh được phát động năm 1970.","Lăng Chủ tịch Hồ Chí Minh khánh thành ngày 29/8/1975; Bảo tàng Hồ Chí Minh được quyết định xây dựng năm 1977 và khánh thành năm 1990. Các bộ Hồ Chí Minh Tuyển tập, Toàn tập lần lượt được xuất bản.","Năm 1987, UNESCO tôn vinh Người là Anh hùng giải phóng dân tộc, nhà văn hóa kiệt xuất. Tư tưởng Hồ Chí Minh được Đảng xác định là nền tảng tư tưởng, kim chỉ nam cho hành động; các cuộc vận động học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh được triển khai rộng rãi."]}]};
